        await b.fs.setDoc(reportChunkRef(b,id,index),{kind:'grc_report_chunk',reportId:id,index:index,byteLength:to-from,data:arrayBufferToBase64(buf),updatedAt:b.fs.serverTimestamp()},{merge:false});
        done++;if(onProgress)onProgress(Math.round(done/total*100));
