  async function deletePdfChunks(b,id,count){
    count=Number(count||0);
    for(var start=0;start<count;start+=20){
      var jobs=[];for(var i=start;i<Math.min(start+20,count);i++)jobs.push(b.fs.deleteDoc(reportChunkRef(b,id,i)));
      await Promise.all(jobs);
    }
  }
  async function updateReportIndex(b,record,removeId){
    await b.fs.runTransaction(b.db,async function(tx){
      var ref=reportIndexRef(b),snap=await tx.get(ref),data=snap.exists()?snap.data():{},list=Array.isArray(data.reports)?data.reports.slice():[];
      if(removeId)list=list.filter(function(x){return String(x&&x.id)!==String(removeId);});
      if(record){list=list.filter(function(x){return String(x&&x.id)!==String(record.id);});list.push(record);}
      tx.set(ref,{reports:list,updatedAt:b.fs.serverTimestamp(),updatedBy:window._fbUser||b.auth.currentUser&&b.auth.currentUser.email||''},{merge:false});
    });
  }
  async function getReportBlobUrl(record){
    var key=String(record.id)+':'+Number(record.version||0)+':'+Number(record.chunkCount||0)+':'+Number(record.fileSize||0);
    if(reportBlobCache[key])return reportBlobCache[key];
    var b=await ensureReportBackend();if(!b.auth.currentUser)throw new Error('not-authenticated');
    var parts=new Array(record.chunkCount);
    for(var start=0;start<record.chunkCount;start+=8){
      var jobs=[];
      for(var i=start;i<Math.min(start+8,record.chunkCount);i++)(function(index){jobs.push(b.fs.getDoc(reportChunkRef(b,record.chunkKey||record.id,index)).then(function(snap){if(!snap.exists())throw new Error('missing-report-chunk-'+index);var d=snap.data()||{};parts[index]=base64ToBytes(d.data||'');}));})(i);
      await Promise.all(jobs);
    }
    var url=URL.createObjectURL(new Blob(parts,{type:'application/pdf'}));reportBlobCache[key]=url;return url;
  }
  async function mountReportViewer(){
    var canvasHosts=Array.prototype.slice.call(document.querySelectorAll('.grc-pdfjs-viewer[data-grc-report-id]'));if(canvasHosts.length)await Promise.all(canvasHosts.map(_grcMountPdfCanvas));
    var frames=Array.prototype.slice.call(document.querySelectorAll('.grc-report-frame[data-grc-report-id]'));if(!frames.length)return;
    await Promise.all(frames.map(async function(frame){var id=frame.getAttribute('data-grc-report-id'),library=frame.getAttribute('data-grc-library')||'reports',record=library==='compliance'?complianceFileDocument(id):(library==='operationalPlan'?OP_PLAN_LIBRARY.find(function(r){return String(r.id)===String(id);}):(library==='guides'?guideRecords().find(function(r){return String(r.id)===String(id);}):REPORT_LIBRARY.find(function(r){return String(r.id)===String(id);})));if(!record)return;try{var url=await getReportBlobUrl(record);if(frame.isConnected)frame.src=url+'#toolbar=1&navpanes=0&view=FitH&page=1';}catch(err){console.error('[GRC PDF] viewer failed',err);if(frame.isConnected)frame.srcdoc='<div style="font:600 16px Arial;padding:40px;text-align:center;color:#7f1d1d">'+String(L('reportLoadError')).replace(/</g,'&lt;')+'</div>';}}));
  }
  window._grcOpenReportFullScreen=async function(id){var popup=window.open('about:blank','_blank');try{var record=REPORT_LIBRARY.find(function(r){return String(r.id)===String(id);});if(!record)throw new Error('report-not-found');var url=await getReportBlobUrl(record);if(popup)popup.location.href=url;else window.location.href=url;}catch(err){if(popup)popup.close();window.alert(L('reportLoadError'));}};
