  function normalizeRecordBeforeSave(type,obj){
    obj=obj||{};
    if(obj.code!==undefined)obj.code=canonicalGovernanceCode(obj.code);
    var d=recordExpiryDate(obj);
    if(d&&d<today())obj.status='expired';
    if(type==='form'&&!obj.status)obj.status='valid';
    if(type==='risk')normalizeRiskClassification(obj);
    return obj;
  }
  function expiringThisYear(r){var d=recordExpiryDate(r),now=today();return!!(d&&d>=now&&d.getFullYear()===now.getFullYear()&&!isExpired(r));}
  function isClosed(r){return['closed','completed'].indexOf(normalizeStatus(r.actionStatus||r.status))>=0;}
  function isOpen(r){return!isClosed(r);}
  function riskScore(r){var likelihood=Number(r&&r.likelihood),impact=Number(r&&r.impact);if(likelihood>=1&&likelihood<=5&&impact>=1&&impact<=5)return likelihood*impact;var saved=Number(r&&r.riskScore);return isFinite(saved)&&saved>0?saved:0;}
  function riskLevel(r){return riskLevelFromScore(riskScore(r));}
  function badge(status){
    var s=normalizeStatus(status),cls='neutral';
    if(['active','valid','open','closed','completed','compliant','successful'].indexOf(s)>=0)cls=s==='open'?'info':'good';
    if(['underReview','inProgress','partial','pendingVerification','pendingApproval','planned'].indexOf(s)>=0)cls='warn';
    if(['expired','invalid','nonCompliant','failed','critical'].indexOf(s)>=0)cls='bad';
    if(['high','medium','major'].indexOf(s)>=0)cls=s==='high'?'warn':'info';
    if(s==='low'||s==='minor'||s==='observation')cls='good';
    if(s==='drill')cls='purple';
    return'<span class="grc-badge '+cls+'">'+esc(L(s))+'</span>';
  }
  function riskActionBadge(status){
    var s=normalizeStatus(status);
    if(s==='open')return'<span class="grc-badge bad">'+esc(L(s))+'</span>';
    return badge(s);
  }
  function emptyRow(cols){return'<tr><td colspan="'+cols+'"><div class="grc-empty"><div class="grc-empty-icon">＋</div><div class="grc-empty-title">'+L('noRecords')+'</div><div class="grc-empty-sub">'+L('noRecordsSub')+'</div></div></td></tr>';}
  function delBtn(collection,id){return'<button class="grc-icon-btn danger" title="'+L('delete')+'" onclick="window._grcDelete(\''+collection+'\',\''+esc(id)+'\')">×</button>';}

