  function enhanceRegisterFilters(){
    if(!app)return;
    app.querySelectorAll('.grc-table').forEach(function(table){
      if(!table.tHead||!table.tBodies.length||table.tHead.querySelector('.grc-filter-row'))return;
      var header=table.tHead.rows[0],body=table.tBodies[0];
      var dataRows=Array.prototype.filter.call(body.rows,function(row){return !row.classList.contains('grc-table-group')&&!row.classList.contains('grc-table-subgroup')&&!row.classList.contains('grc-table-group-empty')&&!row.querySelector('td[colspan]');});
      if(!dataRows.length)return;
      var filterRow=document.createElement('tr');filterRow.className='grc-filter-row';
      Array.prototype.forEach.call(header.cells,function(th,col){
        var cell=document.createElement('th'),select=document.createElement('select');select.setAttribute('aria-label',L('filterByColumn')+' - '+th.textContent.trim());
        var all=document.createElement('option');all.value='';all.textContent=L('filterAll');select.appendChild(all);
        var values={};dataRows.forEach(function(row){var c=row.cells[col],v=c?c.textContent.replace(/\s+/g,' ').trim():'';if(v&&v!=='—')values[v]=1;});
        Object.keys(values).sort(function(a,b){return a.localeCompare(b,isAr()?'ar':'en',{numeric:true});}).forEach(function(v){var o=document.createElement('option');o.value=v;o.textContent=v;select.appendChild(o);});
        select.addEventListener('change',apply);cell.appendChild(select);filterRow.appendChild(cell);
      });
      table.tHead.appendChild(filterRow);
      var wrap=table.closest('.grc-table-wrap');
      if(wrap){var bar=document.createElement('div');bar.className='grc-table-filterbar';bar.innerHTML='<span>'+L('filterByColumn')+'</span><button type="button">'+L('clearFilters')+'</button>';bar.querySelector('button').addEventListener('click',function(){filterRow.querySelectorAll('select').forEach(function(x){x.value='';});apply();});wrap.insertBefore(bar,table);}
      function apply(){
        var filters=Array.prototype.map.call(filterRow.querySelectorAll('select'),function(x){return x.value;});
        dataRows.forEach(function(row){var show=filters.every(function(v,col){if(!v)return true;var c=row.cells[col];return c&&c.textContent.replace(/\s+/g,' ').trim()===v;});row.style.display=show?'':'none';});
        Array.prototype.forEach.call(body.querySelectorAll('.grc-table-subgroup,.grc-table-group'),function(group){var subgroup=group.classList.contains('grc-table-subgroup'),next=group.nextElementSibling,visible=false;while(next){if(next.classList.contains('grc-table-group')||(subgroup&&next.classList.contains('grc-table-subgroup')))break;if(!next.classList.contains('grc-table-subgroup')&&!next.classList.contains('grc-table-group-empty')&&!next.querySelector('td[colspan]')&&next.style.display!=='none'){visible=true;break;}next=next.nextElementSibling;}group.style.display=visible?'':'none';});
      }
    });
  }
  function updateGrcFooterClock(){var el=document.getElementById('grcClockEl');if(!el)return;try{el.textContent=new Date().toLocaleTimeString(isAr()?'ar-SA':'en-GB',{hour:'2-digit',minute:'2-digit'});}catch(_e){var d=new Date(),h=String(d.getHours()).padStart(2,'0'),m=String(d.getMinutes()).padStart(2,'0');el.textContent=h+':'+m;}}
  if(!window._grcFooterClockTimer){window._grcFooterClockTimer=setInterval(updateGrcFooterClock,1000);}
  function render(){if(window._fbUser)enforceLocalGrcScope();var _repairBefore=governanceCodeRepairSnapshot(state);state=repairGovernanceCodeState(state);try{if(_repairBefore!==governanceCodeRepairSnapshot(state)){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));queueSharedStateSave(true);}}catch(_e2){}applyAutomaticExpiry();if(!app||!app.classList.contains('grc-visible'))return;app.setAttribute('dir',isAr()?'rtl':'ltr');try{app.innerHTML=shellHtml();}catch(err){try{console.error('[GRC Render]',err);}catch(_e){}app.innerHTML='<main class="grc-main"><section class="grc-page is-active"><div class="grc-section"><div class="grc-section-title">GRC</div><div class="grc-section-sub">'+esc(String(err&&err.message||err))+'</div></div></section></main>';return;}updateGrcFooterClock();setTimeout(enhanceRegisterFilters,0);setTimeout(enhanceAllRegisterCrud,0);setTimeout(function(){if(typeof window._grcRiskRefreshUi==='function')window._grcRiskRefreshUi();if(typeof window._grcRiskBindHeader==='function')window._grcRiskBindHeader();if(typeof window._grcChatEnsure==='function')window._grcChatEnsure();},0);startSharedStateSync();if(activeTab==='reports'||activeTab==='compliance'||activeTab==='manuals')setTimeout(mountReportViewer,0);if(activeTab==='advisory'&&typeof window._grcAdvisoryMount==='function')setTimeout(window._grcAdvisoryMount,0);}

  function hero(eye,title,desc,actions){return'<div class="grc-hero"><div class="grc-hero-row"><div><div class="grc-eyebrow">'+eye+'</div><h1>'+title+'</h1><p>'+desc+'</p></div><div class="grc-hero-actions">'+(actions||'')+'</div></div></div>';}
  function sectionHead(title,sub,badgeText){return'<div class="grc-section-head"><div><div class="grc-section-title">'+title+'</div><div class="grc-section-sub">'+(sub||'')+'</div></div>'+(badgeText?'<span class="grc-section-badge">'+badgeText+'</span>':'')+'</div>';}
  function metricCard(label,value,cls,sub,onclick){
    var tone=cls||'info',icons={info:'▦',good:'✓',warn:'△',bad:'!',purple:'◇',neutral:'•'};
    return'<div class="grc-metric-card '+tone+' '+(onclick?'clickable':'')+' '+(isAr()?'rtl':'')+'" '+(onclick?'onclick="'+onclick+'" tabindex="0" role="button"':'')+'>'+
      '<div class="grc-metric-top"><span class="grc-metric-icon">'+(icons[tone]||'▦')+'</span></div>'+
      '<div class="grc-metric-value">'+value+'</div><div class="grc-metric-label">'+label+'</div>'+
      '<div class="grc-metric-foot"><span class="grc-metric-sub">'+(sub||'')+'</span>'+(onclick?'<span class="grc-metric-arrow">›</span>':'')+'</div></div>';
  }
  function registerBlock(kind,title,note,button,table){
    var actions=button||'',map=crudMapForTitle(title);
    if(isGrcAdmin()&&map)actions='<div class="grc-register-actions grc-inline-crud-actions">'+registerCrudButtons(map)+'</div>';
    else if(map&&canSubmitRegisterRequest(map.type))actions='<div class="grc-register-actions grc-inline-crud-actions">'+registerCrudButtons(map)+'</div>';
    return'<div class="grc-register-block"><div class="grc-register-titlebar '+kind+'"><div><div class="grc-register-name">'+title+'</div><div class="grc-register-note">'+note+'</div></div>'+actions+'</div>'+table+'</div>';
  }
  function addBtn(type,label,dept){return'<button class="grc-primary-btn" onclick="window._grcOpenForm(\''+type+'\',\''+esc(dept||'')+'\')">＋ '+label+'</button>';}
  function deptColor(dept){return(departmentMeta[dept]&&departmentMeta[dept].color)||'#00A3C4';}
  function deptInk(dept){return(departmentMeta[dept]&&departmentMeta[dept].ink)||deptColor(dept);}
  function deptSoft(dept){return(departmentMeta[dept]&&departmentMeta[dept].soft)||'rgba(0,163,196,.12)';}
  function deptAbbr(dept){return(departmentMeta[dept]&&departmentMeta[dept].abbr)||'FMS Division';}
  function chartHeader(title,total,caption){
    return'<div class="grc-chart-head"><div><div class="grc-chart-title"><span class="grc-chart-mark"></span>'+title+'</div>'+(caption?'<div class="grc-chart-caption">'+esc(caption)+'</div>':'')+'</div>'+(total!==undefined&&total!==null?'<span class="grc-chart-total">'+Number(total||0)+'</span>':'')+'</div>';
  }
  function chartLegend(items,total){
    total=Number(total||items.reduce(function(a,x){return a+Number(x.value||0);},0));
    return'<div class="grc-chart-legend">'+items.map(function(x){var v=Number(x.value||0),share=total?Math.round(v/total*100):0;return'<span><i style="background:'+x.color+'"></i><span class="grc-legend-label">'+esc(x.label)+'</span><small>'+share+'%</small><b>'+v+'</b></span>';}).join('')+'</div>';
  }
  function donutChart(title,items,centerLabel){
    var total=items.reduce(function(a,x){return a+Number(x.value||0);},0),size=144,r=51,circ=2*Math.PI*r,cursor=0,id='grcDonut'+(++chartSeq);
    var rings='';
    if(total){
      items.forEach(function(x){var raw=Number(x.value||0)/total*circ,gap=Math.min(4,raw*.25),len=Math.max(0,raw-gap);rings+='<circle cx="72" cy="72" r="'+r+'" fill="none" stroke="'+x.color+'" stroke-width="15" stroke-linecap="round" stroke-dasharray="'+len+' '+(circ-len)+'" stroke-dashoffset="'+(-cursor)+'" transform="rotate(-90 72 72)"></circle>';cursor+=raw;});
    }
    return'<div class="grc-chart-card grc-donut-card">'+chartHeader(title,total,centerLabel||L('records'))+'<div class="grc-donut-layout"><div class="grc-donut-svg-wrap"><svg class="grc-donut-svg" viewBox="0 0 '+size+' '+size+'" role="img" aria-labelledby="'+id+'"><title id="'+id+'">'+esc(title)+'</title><circle cx="72" cy="72" r="'+r+'" fill="none" stroke="#EDF2F6" stroke-width="15"></circle>'+rings+'</svg><div class="grc-donut-center"><strong>'+total+'</strong><span>'+esc(centerLabel||L('records'))+'</span></div></div>'+chartLegend(items,total)+'</div></div>';
  }
  function emergencyOutcomeDonut(title,success,failed){
    success=Number(success||0);failed=Number(failed||0);
    var total=success+failed,size=112,r=39,circ=2*Math.PI*r,cursor=0,id='grcEmergencyDonut'+(++chartSeq);
    var successColor='#2F9E6F',failedColor='#D94A57',rings='';
    [{value:success,color:successColor},{value:failed,color:failedColor}].forEach(function(x){
      if(!total||!x.value)return;
      var raw=x.value/total*circ,gap=Math.min(3,raw*.18),len=Math.max(0,raw-gap);
      rings+='<circle cx="56" cy="56" r="'+r+'" fill="none" stroke="'+x.color+'" stroke-width="12" stroke-linecap="round" stroke-dasharray="'+len+' '+(circ-len)+'" stroke-dashoffset="'+(-cursor)+'" transform="rotate(-90 56 56)"></circle>';
      cursor+=raw;
    });
    var successPct=total?Math.round(success/total*100):0,failedPct=total?Math.round(failed/total*100):0;
    return'<div class="grc-emergency-outcome-card">'+
      '<div class="grc-emergency-outcome-title">'+esc(title)+'</div>'+
      '<div class="grc-emergency-outcome-body"><div class="grc-emergency-outcome-donut">'+
        '<svg viewBox="0 0 '+size+' '+size+'" role="img" aria-labelledby="'+id+'"><title id="'+id+'">'+esc(title)+'</title><circle cx="56" cy="56" r="'+r+'" fill="none" stroke="#EAF0F3" stroke-width="12"></circle>'+rings+'</svg>'+
        '<div class="grc-emergency-outcome-center"><strong>'+total+'</strong><span>'+esc(L('records'))+'</span></div></div>'+
      '<div class="grc-emergency-outcome-legend">'+
        '<div><i style="background:'+successColor+'"></i><span>'+esc(L('successfulCodes'))+'</span><b>'+successPct+'%</b><small>'+success+'</small></div>'+
        '<div><i style="background:'+failedColor+'"></i><span>'+esc(L('failedCodes'))+'</span><b>'+failedPct+'%</b><small>'+failed+'</small></div>'+
      '</div></div></div>';
  }
  function barChart(title,items){
    var max=Math.max.apply(null,[1].concat(items.map(function(x){return Number(x.value||0);}))),total=items.reduce(function(a,x){return a+Number(x.value||0);},0);
    return'<div class="grc-chart-card grc-horizontal-card">'+chartHeader(title,total,L('records'))+'<div class="grc-bar-list">'+items.map(function(x,i){var v=Number(x.value||0),w=Math.round(v/max*100);return'<div class="grc-bar-row"><div class="grc-bar-head"><span><em>'+(i+1)+'</em>'+esc(x.label)+'</span><b>'+v+'</b></div><div class="grc-bar-track"><span style="width:'+w+'%;--bar-color:'+x.color+'"></span></div></div>';}).join('')+'</div></div>';
  }
  function verticalBarChart(title,items){
    var max=Math.max.apply(null,[1].concat(items.map(function(x){return Number(x.value||0);}))),total=items.reduce(function(a,x){return a+Number(x.value||0);},0);
    return'<div class="grc-chart-card grc-vertical-card">'+chartHeader(title,total,L('records'))+'<div class="grc-vertical-bars">'+items.map(function(x){var v=Number(x.value||0),h=v?Math.max(9,Math.round(v/max*100)):0;return'<div class="grc-vbar-item"><div class="grc-vbar-value">'+v+'</div><div class="grc-vbar-column"><span style="height:'+h+'%;--bar-color:'+x.color+'"></span></div><div class="grc-vbar-label">'+esc(x.label)+'</div></div>';}).join('')+'</div></div>';
  }
  function stackedBarChart(title,rows,legend){
    var grand=rows.reduce(function(a,row){return a+(row.segments||[]).reduce(function(t,s){return t+Number(s.value||0);},0);},0);
    var legendItems=(legend||[]).map(function(item){var value=0;rows.forEach(function(row){(row.segments||[]).forEach(function(seg){if(seg.label===item.label||seg.color===item.color)value+=Number(seg.value||0);});});return{label:item.label,color:item.color,value:value};});
    return'<div class="grc-chart-card grc-stacked-card">'+chartHeader(title,grand,L('records'))+'<div class="grc-stacked-list">'+rows.map(function(row){var total=(row.segments||[]).reduce(function(a,s){return a+Number(s.value||0);},0);return'<div class="grc-stacked-row"><div class="grc-stacked-head"><span>'+esc(row.label)+'</span><b>'+total+'</b></div><div class="grc-stacked-track">'+(row.segments||[]).map(function(s){var w=total?Number(s.value||0)/total*100:0;return'<span title="'+esc(s.label)+': '+Number(s.value||0)+'" style="width:'+w+'%;--segment-color:'+s.color+'"></span>';}).join('')+'</div></div>';}).join('')+'</div>'+chartLegend(legendItems,grand)+'</div>';
  }
  function lineAreaChart(title,items,color){
    color=color||chartPalette.teal;
    var width=700,height=230,left=45,right=22,top=28,bottom=43,max=Math.max.apply(null,[1].concat(items.map(function(x){return Number(x.value||0);}))),usableW=width-left-right,usableH=height-top-bottom,id='grcLineFill'+(++chartSeq);
    var points=items.map(function(x,i){var px=items.length===1?left+usableW/2:left+(usableW*i/(items.length-1)),py=top+usableH-(Number(x.value||0)/max*usableH);return{x:px,y:py,label:x.label,value:Number(x.value||0)};});
    var poly=points.map(function(p){return p.x+','+p.y;}).join(' '),area=points.length?'M '+points[0].x+' '+(height-bottom)+' L '+points.map(function(p){return p.x+' '+p.y;}).join(' L ')+' L '+points[points.length-1].x+' '+(height-bottom)+' Z':'',grid='';
    [0,.25,.5,.75,1].forEach(function(fr){var y=top+usableH*fr;grid+='<line x1="'+left+'" y1="'+y+'" x2="'+(width-right)+'" y2="'+y+'" class="grc-line-grid"/>';});
    return'<div class="grc-chart-card grc-line-card">'+chartHeader(title,items.reduce(function(a,x){return a+Number(x.value||0);},0),L('incidentsByYear'))+'<div class="grc-line-wrap"><svg viewBox="0 0 '+width+' '+height+'" preserveAspectRatio="none" role="img" aria-label="'+esc(title)+'"><defs><linearGradient id="'+id+'" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="'+color+'" stop-opacity=".24"/><stop offset="100%" stop-color="'+color+'" stop-opacity=".015"/></linearGradient></defs>'+grid+'<path d="'+area+'" fill="url(#'+id+')"/><polyline points="'+poly+'" fill="none" stroke="'+color+'" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/>'+points.map(function(p){return'<circle cx="'+p.x+'" cy="'+p.y+'" r="5" fill="#fff" stroke="'+color+'" stroke-width="3"/><text x="'+p.x+'" y="'+(p.y-13)+'" text-anchor="middle" class="grc-line-value">'+p.value+'</text><text x="'+p.x+'" y="'+(height-13)+'" text-anchor="middle" class="grc-line-label">'+esc(p.label)+'</text>';}).join('')+'</svg></div></div>';
  }
  function governanceBuckets(arr){
    var expired=arr.filter(isExpired),due=arr.filter(function(r){return !isExpired(r)&&expiringThisYear(r);}),active=arr.filter(function(r){return ['active','valid','open'].indexOf(normalizeStatus(r.status))>=0&&!isExpired(r)&&!expiringThisYear(r);});
    var used=expired.length+due.length+active.length,other=Math.max(0,arr.length-used);
    return{active:active.length,due:due.length,expired:expired.length,other:other};
  }
  function riskHeatMap(dept){
    var risks=filterDept(state.risks,dept),impacts=[5,4,3,2,1],likelihoods=[5,4,3,2,1],impactLabels={5:'veryHighImpact',4:'highImpact',3:'mediumImpact',2:'lowImpact',1:'veryLowImpact'},likeLabels={5:'almostCertain',4:'likely',3:'possible',2:'unlikely',1:'rare'};
    function heatLevel(score){if(score>=15)return{cls:'very-high',label:L('veryHighRisk')};if(score>=8)return{cls:'high',label:L('highRiskLabel')};if(score>=4)return{cls:'medium',label:L('mediumRiskLabel')};return{cls:'low',label:L('lowRiskLabel')};}
    var headers=impacts.map(function(i){return'<div class="grc-heat-impact-head">'+L(impactLabels[i])+'</div>';}).join('')+'<div class="grc-heat-side-head">'+L('riskLikelihoodAxis')+'</div>';
    var rows=likelihoods.map(function(l){var cells=impacts.map(function(i){var score=l*i,level=heatLevel(score),count=risks.filter(function(r){return Number(r.likelihood)===l&&Number(r.impact)===i;}).length;return'<button type="button" class="grc-heat-cell '+level.cls+'" onclick="window._grcOpenHeatCell(\''+dept+'\','+l+','+i+')"><strong>'+score+'</strong><span>'+level.label+'</span>'+(count?'<em>'+count+' '+L('risksInCell')+'</em>':'')+'</button>';}).join('');return cells+'<div class="grc-heat-like-label">'+L(likeLabels[l])+'</div>';}).join('');
    return'<div class="grc-chart-card grc-heatmap-card"><div class="grc-chart-title">'+L('riskHeatMap')+'</div><div class="grc-heat-impact-title">'+L('riskImpactAxis')+'</div><div class="grc-heat-grid" dir="ltr">'+headers+rows+'</div></div>';
  }
  function departmentPanel(dept,scope,total,second,alert,secondLabel,body){
    var color=deptColor(dept),ink=deptInk(dept),soft=deptSoft(dept),all=[].concat(filterDept(state.policies,dept),filterDept(state.plans,dept),filterDept(state.forms,dept)),expiredCount=all.filter(isExpired).length,expiringCount=all.filter(function(r){return !isExpired(r)&&expiringThisYear(r);}).length;
    return'<section class="grc-department-panel" style="--dept-color:'+color+';--dept-ink:'+ink+';--dept-soft:'+soft+'"><div class="grc-department-accent"></div><div class="grc-department-header"><div class="grc-department-identity"><div class="grc-department-abbr">'+esc(deptAbbr(dept))+'</div><div><div class="grc-department-name">'+esc(deptName(dept))+'</div><div class="grc-department-caption">'+esc(scope)+'</div></div></div><div class="grc-department-summary grc-department-summary-four"><div class="grc-mini-stat"><b>'+Number(total||0)+'</b><span>'+L('total')+'</span></div><div class="grc-mini-stat good"><b>'+Number(second||0)+'</b><span>'+esc(secondLabel||L('valid'))+'</span></div><div class="grc-mini-stat bad"><b>'+expiredCount+'</b><span>'+L('expired')+'</span></div><div class="grc-mini-stat warn"><b>'+expiringCount+'</b><span>'+L('expiringThisYear')+'</span></div></div></div><div class="grc-department-body">'+body+'</div></section>';
  }
  function governanceMetricCards(kind,dept){
    var arr=filterDept(state[kind],dept),expired=arr.filter(isExpired),due=arr.filter(expiringThisYear),active=arr.filter(function(r){return['active','valid','open'].indexOf(normalizeStatus(r.status))>=0&&!isExpired(r);});
    var c=[];
    if(kind==='policies')c=[['totalPolicies',arr.length,'info','total'],['openPolicies',active.length,'good','active'],['expiredPolicies',expired.length,'bad','expired'],['expiringThisYear',due.length,'warn','expiring'],['expiredPolicyRate',pct(expired.length,arr.length),'purple','expired']];
    if(kind==='plans')c=[['totalPlans',arr.length,'info','total'],['activePlans',active.length,'good','active'],['expiredPlans',expired.length,'bad','expired'],['expiringThisYear',due.length,'warn','expiring'],['expiredPlanRate',pct(expired.length,arr.length),'purple','expired']];
    if(kind==='forms')c=[['totalForms',arr.length,'info','total'],['activeForms',active.length,'good','active'],['expiredForms',expired.length,'bad','expired']];
    var gridClass=c.length===4?'cols-4':c.length===3?'cols-3':'';
    return'<div class="grc-metric-grid '+gridClass+'">'+c.map(function(x){return metricCard(L(x[0]),x[1],x[2],L('clickToView'),"window._grcOpenMetric(\'"+kind+"\',\'"+x[3]+"\',\'"+dept+"\')");}).join('')+'</div>';
  }
  function governanceCategoryChart(kind,dept){
    var arr=filterDept(state[kind],dept),b=governanceBuckets(arr);
    var items=[{label:L('valid'),value:b.active,color:chartPalette.green},{label:L('dueThisYear'),value:b.due,color:chartPalette.amber},{label:L('expired'),value:b.expired,color:chartPalette.coral},{label:L('other'),value:b.other,color:chartPalette.slate}];
    var titleMap={policies:'policies',plans:'plans',forms:'forms'};
    return'<div class="grc-chart-grid cols-1 grc-chart-after-metrics">'+donutChart(L(titleMap[kind])+' · '+L('governanceStatusChart'),items,L('records'))+'</div>';
  }
  function formRecords(dept,scope){return filterDept(state.forms,dept).filter(function(r){return String(r.scope||r.formScope||'internal').toLowerCase()===(scope==='external'?'external':'internal');});}
  function formScopeMetrics(dept,scope){var arr=formRecords(dept,scope),expired=arr.filter(isExpired),active=arr.filter(function(r){return['active','valid','open'].indexOf(normalizeStatus(r.status))>=0&&!isExpired(r);});var defs=[['totalForms',arr.length,'info','total'],['activeForms',active.length,'good','active'],['expiredForms',expired.length,'bad','expired']];return'<div class="grc-metric-grid cols-3">'+defs.map(function(x){return metricCard(L(x[0]),x[1],x[2],L('clickToView'),"window._grcOpenFormMetric(\'"+scope+"\',\'"+x[3]+"\',\'"+dept+"\')");}).join('')+'</div>';}
  function formScopeChart(dept,scope){var b=governanceBuckets(formRecords(dept,scope));return'<div class="grc-chart-grid cols-1 grc-chart-after-metrics">'+donutChart(L(scope==='external'?'externalForms':'internalForms')+' · '+L('governanceStatusChart'),[{label:L('valid'),value:b.active,color:chartPalette.green},{label:L('dueThisYear'),value:b.due,color:chartPalette.amber},{label:L('expired'),value:b.expired,color:chartPalette.coral},{label:L('other'),value:b.other,color:chartPalette.slate}],L('records'))+'</div>';}
  function formsTable(dept,scope,grouped){var heads=['name','code','status'];function rowsFor(d){return formRecords(d,scope).map(function(r){return'<tr><td>'+esc(recordName(r))+'</td><td class="grc-id">'+esc(r.code||r.id||'—')+'</td><td>'+badge(isExpired(r)?'expired':r.status)+'</td></tr>';}).join('');}return tableHtml('form',heads,grouped?groupedDepartmentRows(heads.length,rowsFor):rowsFor(dept));}
  function formsSplitOverview(dept,withRegisters,withCharts){return'<div class="grc-form-scope-grid">'+['internal','external'].map(function(scope){var html='<div class="grc-form-scope-panel">'+sectionHead(L(scope==='external'?'externalForms':'internalForms'),deptName(dept))+formScopeMetrics(dept,scope);if(withCharts!==false)html+=formScopeChart(dept,scope);if(withRegisters)html+=registerBlock('form',L(scope==='external'?'externalForms':'internalForms'),deptName(dept),addBtn('form',L('addForm'),dept),formsTable(dept,scope,false));return html+'</div>';}).join('')+'</div>';}
  function governanceOverview(dept,withRegisters,withCharts){
    var sections=[['policies','policies','policyRegister','addPolicy','policy'],['plans','plans','planRegister','addPlan','plan']];
    var html=sections.map(function(s){var out='<div class="grc-section grc-domain-section">'+sectionHead(L(s[1]),deptName(dept),withRegisters?'':'')+governanceMetricCards(s[0],dept);if(withCharts!==false)out+=governanceCategoryChart(s[0],dept);if(withRegisters)out+=registerBlock(s[4],L(s[2]),deptName(dept),addBtn(s[4],L(s[3]),dept),governanceTable(s[0],dept,s[4],false));return out+'</div>';}).join('');
    html+='<div class="grc-section grc-domain-section grc-forms-domain">'+sectionHead(L('forms'),deptName(dept))+governanceMetricCards('forms',dept)+formsSplitOverview(dept,withRegisters,withCharts)+'</div>';return html;
  }


  function riskMetricCards(dept){
    var arr=filterDept(state.risks,dept),closed=arr.filter(isClosed),open=arr.filter(isOpen);
    var levels={critical:[],high:[],medium:[],low:[]};arr.forEach(function(r){levels[riskLevel(r)].push(r);});
    var summary=[
      ['totalRisks',arr.length,'info','total'],
      ['openRisks',open.length,'bad','open'],
      ['closedRisks',closed.length,'good','closed'],
      ['closedRiskRate',pct(closed.length,arr.length),'purple','closed'],
      ['highCriticalRate',pct(levels.high.length+levels.critical.length,arr.length),'bad','highCritical']
    ];
    var levelsRow=[
      ['criticalRisks',levels.critical.length,'bad','critical'],
      ['highRisks',levels.high.length,'warn','high'],
      ['mediumRisks',levels.medium.length,'info','medium'],
      ['lowRisks',levels.low.length,'good','low']
    ];
    function cards(defs,cls){return'<div class="grc-metric-grid '+(cls||'')+'">'+defs.map(function(x){return metricCard(L(x[0]),x[1],x[2],L('clickToView'),'window._grcOpenMetric(\'risks\',\''+x[3]+'\',\''+dept+'\')');}).join('')+'</div>';}
    return cards(summary,'grc-risk-summary-grid')+cards(levelsRow,'cols-4 grc-risk-level-grid');
  }
  function incidentMetricCards(dept){
    var arr=filterDept(state.incidents,dept),closed=arr.filter(isClosed),open=arr.filter(isOpen);
    var defs=[['totalIncidents',arr.length,'info','years'],['openIncidents',open.length,'warn','open'],['closedIncidents',closed.length,'good','closed'],['closedIncidentRate',pct(closed.length,arr.length),'purple','closed']];
    return'<div class="grc-metric-grid cols-4">'+defs.map(function(x){return metricCard(L(x[0]),x[1],x[2],x[3]==='years'?L('incidentsByYear'):L('clickToView'),'window._grcOpenMetric(\'incidents\',\''+x[3]+'\',\''+dept+'\')');}).join('')+'</div>';
  }
  function codeMetricCards(dept){
    var arr=filterDept(state.codes,dept);
    var real=arr.filter(function(r){return normalizeStatus(r.type)==='real';});
    var drill=arr.filter(function(r){return normalizeStatus(r.type)==='drill';});
    var success=arr.filter(function(r){return normalizeStatus(r.status)==='successful';});
    var failed=arr.filter(function(r){return normalizeStatus(r.status)==='failed';});
    var defs=[
      ['totalCodes',arr.length,'info','total'],
      ['realCodes',real.length,'purple','real'],
      ['drillCodes',drill.length,'info','drill'],
      ['successfulCodes',success.length,'good','successful'],
      ['failedCodes',failed.length,'bad','failed'],
      ['failedCodeRate',pct(failed.length,success.length+failed.length),'warn','failedRate']
    ];
    return'<div class="grc-metric-grid cols-6">'+defs.map(function(x){return metricCard(L(x[0]),x[1],x[2],L('clickToView'),'window._grcOpenMetric(\'codes\',\''+x[3]+'\',\''+dept+'\')');}).join('')+'</div>';
  }
  function riskDistributionBars(dept){
    var risks=filterDept(state.risks,dept),levels={critical:0,high:0,medium:0,low:0};risks.forEach(function(r){levels[riskLevel(r)]++;});
    return'<div class="grc-chart-grid cols-1 grc-chart-after-metrics">'+donutChart(L('riskDistributionChart'),[
      {label:L('critical'),value:levels.critical,color:chartPalette.rose},
      {label:L('high'),value:levels.high,color:chartPalette.orange},
      {label:L('medium'),value:levels.medium,color:chartPalette.amber},
      {label:L('low'),value:levels.low,color:chartPalette.green}
    ],L('totalRisks'))+'</div>';
  }
  function riskExposureByDepartmentChart(){
    var items=departmentOrder.map(function(dept){
      var value=filterDept(state.risks,dept).filter(function(r){return['critical','high'].indexOf(riskLevel(r))>=0;}).length;
      return{label:deptName(dept),value:value,color:deptColor(dept)};
    });
    return'<div class="grc-chart-grid cols-1 grc-chart-after-metrics">'+barChart(L('riskExposureChart'),items)+'</div>';
  }
  function riskCategoryChart(dept){
    var map={};filterDept(state.risks,dept).forEach(function(r){var k=String(r.riskCategory||L('other')).trim()||L('other');map[k]=(map[k]||0)+1;});
    var palette=[chartPalette.navy,chartPalette.teal,chartPalette.blue,chartPalette.amber,chartPalette.coral,chartPalette.green,chartPalette.violet];
    var items=Object.keys(map).sort(function(a,b){return map[b]-map[a];}).slice(0,7).map(function(k,i){return{label:k,value:map[k],color:palette[i%palette.length]};});
    if(!items.length)items=[{label:L('noRecords'),value:0,color:chartPalette.slate}];
    return'<div class="grc-chart-grid cols-1 grc-chart-after-metrics">'+barChart(L('riskCategoryChart'),items)+'</div>';
  }
  function incidentTrendChartHtml(dept){
    var incidents=filterDept(state.incidents,dept);
    var open=incidents.filter(isOpen).length;
    var closed=incidents.filter(isClosed).length;
    var items=[
      {label:L('openIncidents'),value:open,color:chartPalette.coral},
      {label:L('closedIncidents'),value:closed,color:chartPalette.green}
    ];
    return'<div class="grc-chart-grid cols-1 grc-chart-after-metrics grc-incident-status-chart">'+donutChart(L('incidentTrendChart'),items,L('incidents'))+'</div>';
  }
  function incidentCategoryTrendChartHtml(dept){
    var incidents=filterDept(state.incidents,dept),categories={};
    incidents.forEach(function(r){
      var category=String(r.category||'').trim()||L('other');
      categories[category]=(categories[category]||0)+1;
    });
    var palette=[chartPalette.teal,chartPalette.navy,chartPalette.blue,chartPalette.amber,chartPalette.coral,chartPalette.green,chartPalette.violet];
    var items=Object.keys(categories).sort(function(a,b){return categories[b]-categories[a]||a.localeCompare(b);}).map(function(category,index){
      return{label:category,value:categories[category],color:palette[index%palette.length]};
    });
    if(!items.length)items=[{label:L('noRecords'),value:0,color:chartPalette.slate}];
    return'<div class="grc-chart-grid cols-1 grc-chart-after-metrics">'+barChart(L('incidentTrendByCategory'),items)+'</div>';
  }
  function codeCharts(dept){
    var codes=filterDept(state.codes,dept),real=codes.filter(function(r){return normalizeStatus(r.type)==='real';}).length,drill=codes.filter(function(r){return normalizeStatus(r.type)==='drill';}).length,success=codes.filter(function(r){return normalizeStatus(r.status)==='successful';}).length,failed=codes.filter(function(r){return normalizeStatus(r.status)==='failed';}).length;
    return'<div class="grc-chart-grid cols-2 grc-chart-after-metrics">'+verticalBarChart(L('codeTypeChart'),[{label:L('realCodes'),value:real,color:chartPalette.navy},{label:L('drillCodes'),value:drill,color:chartPalette.blue}])+donutChart(L('codeOutcomeChart'),[{label:L('successfulCodes'),value:success,color:chartPalette.green},{label:L('failedCodes'),value:failed,color:chartPalette.coral}],L('codes'))+'</div>';
  }
  function riskSection(dept,withRegisters,withCharts){
    var html='<div class="grc-section grc-domain-section">'+sectionHead(L('riskRegister'),deptName(dept))+riskMetricCards(dept);
    if(withCharts!==false){html+=riskHeatMap(dept)+riskDistributionBars(dept)+riskCategoryChart(dept);if(dept==='allFms')html+=riskExposureByDepartmentChart();}
    if(withRegisters)html+=registerBlock('risk',L('riskRegister'),deptName(dept),addBtn('risk',L('addRisk'),dept==='housekeepingRisk'||dept==='laundryRisk'?'housekeeping':dept),riskTable(dept,false));
    return html+'</div>';
  }
  function housekeepingRiskSplit(withRegisters,withCharts){
    return'<div class="grc-housekeeping-risk-split">'+
      '<section class="grc-risk-subgroup housekeeping-subgroup">'+riskSection('housekeepingRisk',withRegisters,withCharts)+'</section>'+
      '<section class="grc-risk-subgroup laundry-subgroup">'+riskSection('laundryRisk',withRegisters,withCharts)+'</section>'+
      '</div>';
  }
  var _grcEmergencySubtypeDefs={
    brown:[
      {key:'electrical',en:'Electrical power supply failure',ar:'انقطاع إمداد الطاقة الكهربائية'},
      {key:'water',en:'Water supply failure',ar:'انقطاع إمداد المياه'},
      {key:'medical gas',en:'Medical gas failure',ar:'تعطل الغازات الطبية'},
      {key:'elevator',en:'Elevators',ar:'تعطل المصاعد'}
    ],
    orange:[
      {key:'chemical',en:'Chemical spill',ar:'انسكاب كيميائي'},
      {key:'biological',en:'Biological spill',ar:'انسكاب بيولوجي'}
    ]
  };
  function emergencyCodeName(code){
    var labels={yellow:isAr()?'الكود الأصفر':'Yellow Code',brown:isAr()?'الكود البني':'Brown Code',red:isAr()?'الكود الأحمر':'Red Code',orange:isAr()?'الكود البرتقالي':'Orange Code'};
    return labels[code]||code;
  }
  function emergencyCodeRows(dept,code){
    return filterDept(state.codes,dept).filter(function(r){
      return String(r.codeType||r.emergencyCode||r.codeName||r.category||'').toLowerCase().indexOf(code)>=0;
    });
  }
  function emergencySubtypeRows(dept,code,sub){
    return emergencyCodeRows(dept,code).filter(function(r){
      var text=String(r.subtype||r.codeSubtype||r.failureType||r.description||r.remarks||'').toLowerCase();
      return text.indexOf(String(sub.key||'').toLowerCase())>=0;
    });
  }
  function emergencyMetricValues(rows){
    var real=rows.filter(function(r){return normalizeStatus(r.type)==='real'||normalizeStatus(r.codeMode)==='real';}).length,
      drill=rows.filter(function(r){return normalizeStatus(r.type)==='drill'||normalizeStatus(r.codeMode)==='drill';}).length,
      success=rows.filter(function(r){return['successful','success','closed'].indexOf(normalizeStatus(r.status||r.outcome))>=0;}).length,
      failed=rows.filter(function(r){return['failed','failure','open'].indexOf(normalizeStatus(r.status||r.outcome))>=0;}).length;
    return{total:rows.length,real:real,drill:drill,success:success,failed:failed,failedRate:pct(failed,success+failed)};
  }
  function emergencyMetricCards(values,caption,onclick){
    var metrics=[['totalCodes',values.total,'info'],['realCodes',values.real,'purple'],['drillCodes',values.drill,'info'],['successfulCodes',values.success,'good'],['failedCodes',values.failed,'bad'],['failedCodeRate',values.failedRate,'warn']];
    return'<div class="grc-metric-grid cols-6">'+metrics.map(function(x){return metricCard(L(x[0]),x[1],x[2],caption,onclick||'');}).join('')+'</div>';
  }
  function emergencyCodeGroups(dept){
    var defs={maintenance:['brown','yellow'],safety:['red','brown','yellow'],housekeeping:['orange','yellow'],allFms:['red','brown','orange','yellow']},
      colors={yellow:'#d4a900',brown:'#8b5e3c',red:'#cf3e48',orange:'#ef7d22'},
      list=defs[dept]||['yellow'];
    return'<div class="grc-emergency-code-groups">'+list.map(function(code){
      var caption=emergencyCodeName(code),rows=emergencyCodeRows(dept,code),
        hasTypes=code==='brown'||code==='orange',
        click=hasTypes?"window._grcOpenEmergencyTypes('"+dept+"','"+code+"')":'';
      return'<div class="grc-emergency-code-type code-'+code+'" style="--emergency-color:'+colors[code]+'">'+
        '<h4><span></span>'+caption+'</h4>'+emergencyMetricCards(emergencyMetricValues(rows),hasTypes?(isAr()?'اضغط لعرض الأنواع':'Click to view types'):caption,click)+'</div>';
    }).join('')+'</div>';
  }
  window._grcCloseEmergencyTypes=function(){
    var modal=document.getElementById('_grcEmergencyTypesModal');if(modal)modal.remove();
  };
  window._grcOpenEmergencyTypes=function(dept,code){
    window._grcCloseEmergencyTypes();
    var defs=(_grcEmergencySubtypeDefs[code]||[]).slice();
    if(dept==='safety'&&code==='brown')defs=defs.filter(function(x){return x.key==='water';});
    var modal=document.createElement('div');modal.id='_grcEmergencyTypesModal';modal.className='grc-emergency-types-modal';
    modal.innerHTML='<div class="grc-emergency-types-backdrop" onclick="window._grcCloseEmergencyTypes()"></div>'+
      '<section class="grc-emergency-types-dialog"><header><div><h3>'+esc(emergencyCodeName(code))+'</h3><p>'+(isAr()?'أنواع الكود وبيانات كل نوع':'Code types and metrics for each type')+'</p></div><button type="button" onclick="window._grcCloseEmergencyTypes()">×</button></header>'+
      '<div class="grc-emergency-types-content">'+defs.map(function(sub){
        var title=isAr()?sub.ar:sub.en,rows=emergencySubtypeRows(dept,code,sub),values=emergencyMetricValues(rows),
          chartItems=[
            {label:L('successfulCodes'),value:values.success,color:chartPalette.green},
            {label:L('failedCodes'),value:values.failed,color:chartPalette.coral}
          ],
          chartTitle=title+' · '+(isAr()?'نتيجة الكود':'Code Outcome');
        return'<article class="grc-emergency-type-panel"><h4>'+esc(title)+'</h4>'+
          emergencyMetricCards(values,title,'')+
          '<div class="grc-emergency-subtype-chart">'+emergencyOutcomeDonut(chartTitle,values.success,values.failed)+'</div></article>';
      }).join('')+'</div></section>';
    document.body.appendChild(modal);
  };
  function riskOverview(dept,withRegisters,withCharts){
    var html=dept==='housekeeping'?housekeepingRiskSplit(withRegisters,withCharts):riskSection(dept,withRegisters,withCharts);
    html+='<div class="grc-section grc-domain-section">'+sectionHead(L('incidents'),deptName(dept))+incidentMetricCards(dept);
    if(withCharts!==false)html+=incidentTrendChartHtml(dept)+incidentCategoryTrendChartHtml(dept);
    if(withRegisters)html+=registerBlock('incident',L('incidentRegister'),deptName(dept),addBtn('incident',L('addIncident'),dept),incidentTable(dept,false));
    if(dept!=='projects'){
      html+='</div><div class="grc-section grc-domain-section">'+sectionHead(L('codes'),deptName(dept))+codeMetricCards(dept)+emergencyCodeGroups(dept);
      if(withCharts!==false)html+=codeCharts(dept);
      if(withRegisters)html+=registerBlock('code',L('codeRegister'),deptName(dept),addBtn('code',L('addCode'),dept),codeTable(dept,false));
    }
    return html+'</div>';
  }
  function governanceCharts(dept){return governanceCategoryChart('policies',dept)+governanceCategoryChart('plans',dept)+governanceCategoryChart('forms',dept);}
  function riskCharts(dept){return riskHeatMap(dept)+riskDistributionBars(dept)+riskCategoryChart(dept)+incidentTrendChartHtml(dept)+incidentCategoryTrendChartHtml(dept)+codeCharts(dept);}
  function governanceDepartmentPanel(dept){
    var all=[];['policies','plans','forms'].forEach(function(k){all=all.concat(filterDept(state[k],dept));});
    var active=all.filter(function(r){return['active','valid','open'].indexOf(normalizeStatus(r.status))>=0&&!isExpired(r);}).length;
    var alert=all.filter(function(r){return isExpired(r)||expiringThisYear(r);}).length;
    return departmentPanel(dept,L('governance')+' · '+L('departmentRecords'),all.length,active,alert,L('valid'),governanceOverview(dept,false,true));
  }
  function riskDepartmentPanel(dept){
    var risks=filterDept(state.risks,dept),
      incidents=filterDept(state.incidents,dept),
      openRisks=risks.filter(isOpen).length,
      highCritical=risks.filter(function(r){return['critical','high'].indexOf(riskLevel(r))>=0;}).length,
      openIncidents=incidents.filter(isOpen).length,
      color=deptColor(dept),ink=deptInk(dept),soft=deptSoft(dept),
      highCriticalLabel=isAr()?'المخاطر العالية والحرجة':'High &<br>Critical Risks';
    return'<section class="grc-department-panel" style="--dept-color:'+color+';--dept-ink:'+ink+';--dept-soft:'+soft+'">'+
      '<div class="grc-department-accent"></div>'+
      '<div class="grc-department-header"><div class="grc-department-identity"><div class="grc-department-abbr">'+esc(deptAbbr(dept))+'</div><div><div class="grc-department-name">'+esc(deptName(dept))+'</div><div class="grc-department-caption">'+esc(L('risk')+' · '+L('departmentRecords'))+'</div></div></div>'+
      '<div class="grc-department-summary grc-department-summary-four grc-risk-clean-summary">'+
        '<div class="grc-mini-stat grc-risk-total"><b>'+risks.length+'</b><span>'+L('totalRisks')+'</span></div>'+
        '<div class="grc-mini-stat grc-risk-alert"><b>'+openRisks+'</b><span>'+L('openRisks')+'</span></div>'+
        '<div class="grc-mini-stat grc-risk-alert"><b>'+highCritical+'</b><span>'+highCriticalLabel+'</span></div>'+
        '<div class="grc-mini-stat grc-risk-alert"><b>'+openIncidents+'</b><span>'+L('openIncidents')+'</span></div>'+
      '</div></div><div class="grc-department-body">'+riskOverview(dept,false,true)+'</div></section>';
  }
  function executiveGovernancePortfolio(){
    var defs=[['policies','policies','policy'],['plans','plans','plan'],['forms','forms','form']];
    var cards='<div class="grc-metric-grid cols-3 grc-exec-portfolio-cards">'+defs.map(function(d){var arr=filterDept(state[d[0]],'allFms'),b=governanceBuckets(arr),sub=b.active+' '+L('valid')+' · '+b.expired+' '+L('expired');return metricCard(L(d[1]),arr.length,'info',sub,'window._grcOpenMetric(\''+d[0]+'\',\'total\',\'allFms\')');}).join('')+'</div>';
    var rows=defs.map(function(d){var b=governanceBuckets(filterDept(state[d[0]],'allFms'));return{label:L(d[1]),segments:[{label:L('valid'),value:b.active,color:chartPalette.green},{label:L('dueThisYear'),value:b.due,color:chartPalette.amber},{label:L('expired'),value:b.expired,color:chartPalette.coral},{label:L('other'),value:b.other,color:chartPalette.slate}]};});
    var legend=[{label:L('valid'),value:0,color:chartPalette.green},{label:L('dueThisYear'),value:0,color:chartPalette.amber},{label:L('expired'),value:0,color:chartPalette.coral},{label:L('other'),value:0,color:chartPalette.slate}];
    var volume=defs.map(function(d,i){return{label:L(d[1]),value:filterDept(state[d[0]],'allFms').length,color:[chartPalette.teal,chartPalette.blue,chartPalette.navy][i]};});
    return cards+'<div class="grc-chart-grid cols-2 grc-exec-chart-grid">'+stackedBarChart(L('governanceStatusChart'),rows,legend)+verticalBarChart(L('governanceVolumeChart'),volume)+'</div>';
  }
  function executiveRiskPortfolio(){
    return'<div class="grc-exec-risk-summary">'+riskMetricCards('allFms')+'</div>'+
      '<div class="grc-exec-risk-visuals"><div class="grc-exec-risk-heat">'+riskHeatMap('allFms')+'</div><div class="grc-exec-risk-side">'+riskDistributionBars('allFms')+riskExposureByDepartmentChart()+'</div></div>'+
      '<div class="grc-exec-operations-grid"><section class="grc-exec-ops-panel"><div class="grc-exec-ops-head"><div><h3>'+L('incidents')+'</h3><p>'+L('incidentTrendChart')+'</p></div><span>'+state.incidents.length+'</span></div>'+incidentMetricCards('allFms')+incidentTrendChartHtml('allFms')+incidentCategoryTrendChartHtml('allFms')+'</section>'+
      '<section class="grc-exec-ops-panel"><div class="grc-exec-ops-head"><div><h3>'+L('codes')+'</h3><p>'+L('codeOutcomeChart')+'</p></div><span>'+state.codes.length+'</span></div>'+codeMetricCards('allFms')+codeCharts('allFms')+'</section></div>';
  }
  function executiveSnapshotCards(){
    var gov=countFor('governance');
    var risks=state.risks||[],openRisk=risks.filter(isOpen).length;
    var incidents=state.incidents||[],openIncident=incidents.filter(isOpen).length;
    var codes=state.codes||[],success=codes.filter(function(r){return normalizeStatus(r.status)==='successful';}).length,failed=codes.filter(function(r){return normalizeStatus(r.status)==='failed';}).length;
    return'<div class="grc-exec-snapshot-grid">'+
      metricCard(L('governanceRecords'),gov,'info',L('allDepartments'),'window._grcSwitch(\'governance\')')+
      metricCard(L('openRisks'),openRisk,'warn',L('allDepartments'),'window._grcOpenMetric(\'risks\',\'open\',\'allFms\')')+
      metricCard(L('openIncidents'),openIncident,'bad',L('allDepartments'),'window._grcOpenMetric(\'incidents\',\'open\',\'allFms\')')+
      metricCard(L('failedCodeRate'),pct(failed,success+failed),'purple',L('codes'),'window._grcOpenMetric(\'codes\',\'failedRate\',\'allFms\')')+
      '</div>';
  }
  function executiveComplianceSummary(dept){
    var c=cbahiSummary(dept),j=jciSummary(dept);
    var cApplicable=Math.max(0,c.total-c.na),jApplicable=Math.max(0,j.total-j.na),den=(cApplicable+jApplicable)*2;
    var score=(c.rate/100)*(cApplicable*2)+(j.rate/100)*(jApplicable*2);
    return{total:c.total+j.total,fully:c.fully+j.fully,partial:c.partial,notmet:c.notmet+j.notmet,na:c.na+j.na,rate:den?Math.round((score/den)*10000)/100:0};
  }
