  function executiveReportStats(){
    var now=new Date(),current=now.getFullYear(),completedQuarter=Math.floor((now.getMonth()+1)/3);
    var uploaded=REPORT_LIBRARY.filter(function(r){return r.group==='annual'||r.group==='quarterly';});
    function has(type,year,q){return uploaded.some(function(r){return r.type===type&&Number(r.year)===Number(year)&&Number(r.quarter||0)===Number(q||0);});}
    var expected=[];
    // Historical years before 2026 are counted only when a real file exists.
    uploaded.forEach(function(r){if(Number(r.year)<2026)expected.push({type:r.type,year:Number(r.year),quarter:Number(r.quarter||0),available:true});});
    // From 2026 onward, completed periods are expected and may be Not Available.
    for(var y=2026;y<=current;y++){
      var lastQuarter=y<current?4:completedQuarter;
      for(var q=1;q<=lastQuarter;q++){
        expected.push({type:'quarterlyReport',year:y,quarter:q,available:has('quarterlyReport',y,q)});
        expected.push({type:'quarterlyExecutive',year:y,quarter:q,available:has('quarterlyExecutive',y,q)});
      }
      if(y<current){
        expected.push({type:'annualReport',year:y,quarter:0,available:has('annualReport',y,0)});
        expected.push({type:'annualExecutive',year:y,quarter:0,available:has('annualExecutive',y,0)});
      }
    }
    // Include uploaded current/future records once, without inventing missing future periods.
    uploaded.forEach(function(r){
      var exists=expected.some(function(x){return x.type===r.type&&x.year===Number(r.year)&&x.quarter===Number(r.quarter||0);});
      if(!exists)expected.push({type:r.type,year:Number(r.year),quarter:Number(r.quarter||0),available:true});
    });
    function count(type){return expected.filter(function(x){return x.type===type&&x.available;}).length;}
    return{
      total:expected.length,
      available:expected.filter(function(x){return x.available;}).length,
      unavailable:expected.filter(function(x){return !x.available;}).length,
      quarterly:count('quarterlyReport'),
      quarterlyExecutive:count('quarterlyExecutive'),
      annual:count('annualReport'),
      annualExecutive:count('annualExecutive')
    };
  }
