  function _grcRemoveInitiativesModal(){
    var modal=document.getElementById('_grcInitiativesModal');
    if(modal)modal.remove();
    document.body.classList.remove('grc-initiatives-open');
  }
  window._grcCloseInitiatives=function(useHistory){
    var hasState=history.state&&history.state.grcInitiativesModal;
    _grcRemoveInitiativesModal();
    if(useHistory!==false&&hasState)history.back();
  };
  window._grcOpenInitiatives=function(filter,fromHistory){
    filter=filter||'all';
    var source=(state.initiatives&&state.initiatives.length)?state.initiatives:INITIATIVE_SEED,
      rows=source.filter(function(r){return filter==='all'||normalizeStatus(r.status)===filter;});
    _grcRemoveInitiativesModal();

    if(!fromHistory){
      if(history.state&&history.state.grcInitiativesModal){
        history.replaceState(Object.assign({},history.state,{grcInitiativesFilter:filter}),'',location.href);
      }else{
        history.pushState(Object.assign({},history.state||{},{grcInitiativesModal:true,grcInitiativesFilter:filter}),'',location.href);
      }
    }

    var title=filter==='selected'
      ?(isAr()?'المبادرات المختارة':'Selected Initiatives')
      :(filter==='proposed'
        ?(isAr()?'المبادرات المقترحة':'Proposed Initiatives')
        :(isAr()?'جميع المبادرات':'All Initiatives')),
      ov=document.createElement('div');

    ov.id='_grcInitiativesModal';
    ov.className='grc-modal-backdrop grc-initiatives-backdrop';
    ov.innerHTML='<div class="grc-modal wide grc-initiatives-modal">'+
      '<div class="grc-modal-head">'+
        '<div><div class="grc-modal-title">'+title+'</div><div class="grc-modal-sub">'+rows.length+' '+L('records')+'</div></div>'+
        '<div class="grc-initiative-modal-actions">'+
          '<button type="button" class="grc-btn ghost" id="_grcInitiativesBack">← '+L('backOneLevel')+'</button>'+
          '<button type="button" class="grc-modal-close" id="_grcInitiativesClose">×</button>'+
        '</div>'+
      '</div>'+
      '<div class="grc-modal-body">'+
        '<div class="grc-initiative-toolbar">'+
          '<input id="_grcInitiativeSearch" type="search" placeholder="'+(isAr()?'ابحث باسم المبادرة بالعربي أو الإنجليزي':'Search initiatives in Arabic or English')+'">'+
          '<div class="grc-initiative-filters">'+
            '<button type="button" data-filter="all" class="'+(filter==='all'?'active':'')+'">'+(isAr()?'الكل':'All')+'</button>'+
            '<button type="button" data-filter="selected" class="'+(filter==='selected'?'active':'')+'">'+(isAr()?'المختارة':'Selected')+'</button>'+
            '<button type="button" data-filter="proposed" class="'+(filter==='proposed'?'active':'')+'">'+(isAr()?'المقترحة':'Proposed')+'</button>'+
          '</div>'+
        '</div>'+
        '<div id="_grcInitiativeCards" class="grc-initiative-card-grid">'+rows.map(initiativeCard).join('')+'</div>'+
      '</div></div>';

    document.body.appendChild(ov);
    document.body.classList.add('grc-initiatives-open');

    document.getElementById('_grcInitiativesClose').addEventListener('click',function(){window._grcCloseInitiatives(true);});
    document.getElementById('_grcInitiativesBack').addEventListener('click',function(){window._grcCloseInitiatives(true);});

    ov.querySelectorAll('[data-filter]').forEach(function(btn){
      btn.addEventListener('click',function(){
        window._grcOpenInitiatives(btn.getAttribute('data-filter'),false);
      });
    });

    var input=document.getElementById('_grcInitiativeSearch');
    input.addEventListener('input',function(){
      var q=String(input.value||'').toLowerCase().trim();
      ov.querySelectorAll('.grc-initiative-card').forEach(function(card){
        card.style.display=!q||String(card.getAttribute('data-search')||'').toLowerCase().indexOf(q)>=0?'':'none';
      });
    });

    ov.addEventListener('click',function(e){
      if(e.target===ov)window._grcCloseInitiatives(true);
    });
  };
  window.addEventListener('popstate',function(){
    var modal=document.getElementById('_grcInitiativesModal');
    if(modal&&!history.state?.grcInitiativesModal){
      _grcRemoveInitiativesModal();
      return;
    }
    if(history.state&&history.state.grcInitiativesModal){
      window._grcOpenInitiatives(history.state.grcInitiativesFilter||'all',true);
    }
  });
  document.addEventListener('click',function(e){
    var card=e.target&&e.target.closest?e.target.closest('[data-initiative-filter]'):null;
    if(card&&typeof window._grcOpenInitiatives==='function'){
      e.preventDefault();
      e.stopPropagation();
      window._grcOpenInitiatives(card.getAttribute('data-initiative-filter')||'all');
    }
  },true);
