  function reportTypeCards(group){return reportGroupTypes(group).map(function(type){var count=reportCount(type),icon=type.indexOf('Executive')>=0?'◫':'▥',available=count>0;return'<button class="grc-report-year-card grc-report-kind-card" onclick="window._grcReportType(\''+type+'\')"><span class="grc-report-kind-icon">'+icon+'</span><strong>'+reportTypeLabel(type)+'</strong><small>'+count+' '+L('reportDocuments')+'</small><span class="grc-report-availability '+(available?'':'off')+'">'+L(available?'available':'unavailable')+'</span></button>';}).join('');}
  function reportYearCards(type){return reportYears().map(function(y){var count=reportCount(type,y),available=count>0;return'<button class="grc-report-year-card" onclick="window._grcReportYear('+y+')"><strong>'+y+'</strong><small>'+count+' '+L('reportDocuments')+'</small><span class="grc-report-availability '+(available?'':'off')+'">'+L(available?'available':'unavailable')+'</span></button>';}).join('');}
  function reportQuarterCards(type,year){return[1,2,3,4].map(function(q){var r=reportFind(type,year,q),available=!!r;return'<button class="grc-quarter-card '+(available?'':'disabled')+'" '+(available?'onclick="window._grcReportQuarter('+q+')"':'disabled')+'><span class="q-index">Q'+q+'</span>'+L('q'+q)+'<small>'+L(available?'available':'unavailable')+'</small></button>';}).join('');}
  function fileSizeText(bytes){bytes=Number(bytes||0);if(!bytes)return'';if(bytes>=1048576)return(bytes/1048576).toFixed(bytes>=10485760?0:1)+' MB';return Math.max(1,Math.round(bytes/1024))+' KB';}
  function reportPeriodText(r){return r.group==='annual'?String(r.year):String(r.year)+' · '+L('q'+Number(r.quarter||1));}
  function reportFallbackCode(r){var executive=String(r.type||'').indexOf('Executive')>=0;if(r.group==='annual')return executive?'PRT-EAR-'+r.year:'PRT-AR-'+r.year;return executive?'PRT-EQR-'+r.year+'-'+Number(r.quarter||1):'RPT-QR-'+r.year+'-'+Number(r.quarter||1);}
  function reportRegisterTable(){
    var now=new Date(),current=now.getFullYear(),completedQuarter=Math.max(0,Math.ceil((now.getMonth()+1)/3)-1),expected=[];
    function actual(type,year,quarter){return REPORT_LIBRARY.find(function(r){return (r.group==='annual'||r.group==='quarterly')&&String(r.type)===String(type)&&Number(r.year)===Number(year)&&Number(r.quarter||0)===Number(quarter||0);})||null;}
    function add(type,group,year,quarter){var r=actual(type,year,quarter),titles=defaultReportTitles(group,type.indexOf('Executive')>=0?'executive':'report',year,quarter);expected.push({record:r,type:type,group:group,year:year,quarter:quarter||null,titleEn:r&&r.titleEn||titles.en,titleAr:r&&r.titleAr||titles.ar,code:r&&r.code&&!/^RPT-FMS(?: Division)?-/.test(r.code)?r.code:reportFallbackCode({type:type,group:group,year:year,quarter:quarter}),available:!!r});}
    for(var y=2026;y<=current;y++){
      if(y<current){add('annualExecutive','annual',y,null);add('annualReport','annual',y,null);}
      var lastQuarter=y<current?4:completedQuarter;
      for(var q=1;q<=lastQuarter;q++){add('quarterlyExecutive','quarterly',y,q);add('quarterlyReport','quarterly',y,q);}
    }
    REPORT_LIBRARY.forEach(function(r){
      if(r.group!=='annual'&&r.group!=='quarterly')return;
      var exists=expected.some(function(x){
        return String(x.type)===String(r.type)&&Number(x.year)===Number(r.year)&&Number(x.quarter||0)===Number(r.quarter||0);
      });
      // Before 2026, include only reports that actually have an uploaded file.
      // From 2026 onward, completed missing periods are generated above as Not Available.
      if(!exists){
        var titles=defaultReportTitles(r.group,r.type.indexOf('Executive')>=0?'executive':'report',r.year,r.quarter);
        expected.push({
          record:r,
          type:r.type,
          group:r.group,
          year:r.year,
          quarter:r.quarter||null,
          titleEn:r.titleEn||titles.en,
          titleAr:r.titleAr||titles.ar,
          code:r.code&&!/^RPT-FMS(?: Division)?-/.test(r.code)?r.code:reportFallbackCode(r),
          available:true
        });
      }
    });
    expected.sort(function(a,b){return b.year-a.year||Number(b.quarter||0)-Number(a.quarter||0)||String(a.type).localeCompare(String(b.type));});
    var rows=expected.map(function(x){var status=x.available?'available':'unavailable';return'<tr><td class="grc-id">'+esc(x.code)+'</td><td>'+esc(isAr()?x.titleAr:x.titleEn)+'</td><td>'+esc(x.group==='annual'?L('annualReports'):L('quarterlyReports'))+'</td><td>'+esc(x.group==='annual'?String(x.year):String(x.year)+' · '+L('q'+Number(x.quarter)))+'</td><td><span class="grc-report-availability '+(x.available?'':'off')+'">'+L(status)+'</span></td></tr>';}).join('');
    return tableHtml('policy',['reportCode','reportName','reportFamily','reportPeriod','reportStatus'],rows);
  }
  function reportRegisterBlock(){return'<div class="grc-section grc-report-register-section">'+registerBlock('policy',L('reportRegister'),L('reportRegisterDesc'),'',reportRegisterTable())+'</div>';}
  function reportAdminToolbar(){if(!isGrcAdmin())return'';return'<div class="grc-report-adminbar"><div><strong>'+L('reportManager')+'</strong><small>'+L('reportManagerDesc')+'</small></div><div class="grc-report-admin-actions"><button class="secondary" onclick="window._grcRefreshReports()">↻ '+L('refreshReports')+'</button><button class="primary" onclick="window._grcOpenReportUpload()">＋ '+L('uploadReport')+'</button></div></div>';}
  function reportViewerHtml(r){
    if(!r)return'<div class="grc-report-empty"><b>'+L('unavailable')+'</b>'+L('noReportAvailable')+'</div>';
    var meta=Number(r.year)+(r.quarter?' · '+L('q'+r.quarter):'');if(Number(r.pages||0)>0)meta+=' · '+Number(r.pages)+' '+L('pages');else if(r.fileSize)meta+=' · '+fileSizeText(r.fileSize);
    var actions='<button onclick="window._grcOpenReportFullScreen(\''+esc(r.id)+'\')">'+L('openFullScreen')+'</button>';
    if(isGrcAdmin())actions='<button class="replace" onclick="window._grcOpenReportUpload(\''+esc(r.id)+'\')">'+L('replaceReport')+'</button><button class="danger" onclick="window._grcDeleteReport(\''+esc(r.id)+'\')">'+L('deleteReport')+'</button>'+actions;
    return'<div class="grc-report-viewer-card"><div class="grc-report-viewer-head"><div><div class="grc-report-viewer-title">'+esc(reportTitle(r))+'</div><div class="grc-report-viewer-meta">'+meta+'</div></div><div class="grc-report-viewer-actions">'+actions+'</div></div>'+pdfSearchBar(r.id,'reports')+'<div class="grc-report-viewer-help">'+(isAr()?'اكتب كلمة ثم استخدم السابق والتالي للتنقل بين النتائج داخل جميع صفحات الملف.':'Type a word, then use Previous and Next to move through matches across the whole PDF.')+'</div><div class="grc-pdfjs-viewer" data-grc-library="reports" data-grc-report-id="'+esc(r.id)+'" aria-label="'+esc(reportTitle(r))+'"></div></div>';
  }
  function reportBackButton(){return'<div class="grc-report-back-row"><button type="button" class="grc-btn ghost" onclick="window._grcReportBack()">← '+L('backOneLevel')+'</button></div>'; }
  function reportsPage(){ensureOperationalPlanStyles();
    var content=hero('GRC · Reporting',L('reportsTitle'),L('reportsDesc'))+(reportNav.group?reportBackButton():'')+reportAdminToolbar()+reportBreadcrumb();
    if(!reportLibraryLoaded){loadReportLibrary(false);return content+'<div class="grc-report-loading">'+L('reportsLoading')+'</div>';}
    if(reportLibraryError)return content+'<div class="grc-report-error">'+L('reportLoadError')+'<div style="margin-top:12px"><button class="grc-upload-primary" onclick="window._grcRefreshReports()">'+L('refreshReports')+'</button></div></div>';
    if(!reportNav.group)return content+reportTopCards()+reportMetricsAndCharts();
    if(!reportNav.type)return content+sectionHead(L('selectReportType'),L(reportNav.group==='annual'?'annualReports':'quarterlyReports'))+'<div class="grc-report-type-grid">'+reportTypeCards(reportNav.group)+'</div>';
    if(!reportNav.year)return content+sectionHead(L('selectYear'),reportTypeLabel(reportNav.type))+'<div class="grc-report-year-grid">'+reportYearCards(reportNav.type)+'</div>';
    if(reportNav.group==='quarterly'&&!reportNav.quarter)return content+sectionHead(L('selectQuarter'),reportTypeLabel(reportNav.type)+' · '+reportNav.year)+'<div class="grc-quarter-grid">'+reportQuarterCards(reportNav.type,reportNav.year)+'</div>';
    return content+sectionHead(L('reportViewer'),reportTypeLabel(reportNav.type))+reportViewerHtml(reportFind(reportNav.type,reportNav.year,reportNav.quarter));
  }
  function defaultReportTitles(group,kind,year,quarter){
    var q=quarter?'Q'+quarter+' ':'';
    if(group==='annual'&&kind==='executive')return{en:'Annual Executive Summary - '+year,ar:'الملخص التنفيذي السنوي لعام '+year};
    if(group==='annual')return{en:'Facility Management & Safety Division Annual Report - '+year,ar:'التقرير السنوي لإدارة المرافق والسلامة لعام '+year};
    if(kind==='executive')return{en:'Executive Summary - '+q+year,ar:'الملخص التنفيذي للربع '+quarter+' لعام '+year};
    return{en:'Facility Management & Safety Division Quarterly Report - '+q+year,ar:'التقرير الربعي '+quarter+' لإدارة المرافق والسلامة لعام '+year};
  }
  function reportTypeFromForm(group,kind){return group==='annual'?(kind==='executive'?'annualExecutive':'annualReport'):(kind==='executive'?'quarterlyExecutive':'quarterlyReport');}
  function reportIdFor(type,year,quarter){return type+'_'+Number(year)+'_'+(quarter?('q'+Number(quarter)):'annual');}
  window._grcRefreshReports=function(){reportLibraryLoaded=false;reportLibraryError='';loadReportLibrary(true);render();};
  window._grcOpenReportUpload=function(existingId){
    if(!isGrcAdmin())return;
    var existing=existingId?REPORT_LIBRARY.find(function(r){return String(r.id)===String(existingId);}):null;
    var old=document.getElementById('_grcReportUploadModal');if(old)old.remove();
    var now=new Date().getFullYear(),group=existing?existing.group:'quarterly',kind=existing&&String(existing.type).indexOf('Executive')>=0?'executive':'report',year=existing?existing.year:now,quarter=existing&&existing.quarter?existing.quarter:1;
    var ov=document.createElement('div');ov.id='_grcReportUploadModal';ov.className='grc-modal-backdrop';
    ov.innerHTML='<div class="grc-modal"><div class="grc-modal-head"><div><div class="grc-modal-title">'+L(existing?'replaceReport':'uploadReport')+'</div><div class="grc-modal-sub">'+L('reportManagerDesc')+'</div></div><button class="grc-modal-close" type="button" onclick="document.getElementById(\'_grcReportUploadModal\').remove()">×</button></div><form novalidate class="grc-modal-body" id="_grcReportUploadForm"><div class="grc-report-upload-grid">'+
      '<div class="grc-report-upload-field"><label>'+L('reportFamily')+'</label><select name="group" id="_grcUploadGroup"><option value="quarterly" '+(group==='quarterly'?'selected':'')+'>'+L('quarterlyReports')+'</option><option value="annual" '+(group==='annual'?'selected':'')+'>'+L('annualReports')+'</option></select></div>'+
      '<div class="grc-report-upload-field"><label>'+L('reportKind')+'</label><select name="kind"><option value="report" '+(kind==='report'?'selected':'')+'>'+L('facilitiesReport')+'</option><option value="executive" '+(kind==='executive'?'selected':'')+'>'+L('executiveSummary')+'</option></select></div>'+
      '<div class="grc-report-upload-field"><label>'+L('reportYear')+'</label><input name="year" type="number" min="2020" max="2100" required value="'+Number(year)+'"></div>'+
      '<div class="grc-report-upload-field" id="_grcUploadQuarterWrap"><label>'+L('reportQuarter')+'</label><select name="quarter"><option value="1" '+(quarter===1?'selected':'')+'>'+L('q1')+'</option><option value="2" '+(quarter===2?'selected':'')+'>'+L('q2')+'</option><option value="3" '+(quarter===3?'selected':'')+'>'+L('q3')+'</option><option value="4" '+(quarter===4?'selected':'')+'>'+L('q4')+'</option></select></div>'+
      '<div class="grc-report-upload-field"><label>'+L('reportTitleEn')+'</label><input name="titleEn" type="text" value="'+esc(existing&&existing.titleEn||'')+'"></div>'+
      '<div class="grc-report-upload-field"><label>'+L('reportTitleAr')+'</label><input name="titleAr" type="text" dir="rtl" value="'+esc(existing&&existing.titleAr||'')+'"></div>'+
      '<div class="grc-report-upload-field"><label>'+L('reportCode')+'</label><input name="code" type="text" value="'+esc(existing&&existing.code||'')+'" placeholder="RPT-QR-2026-2"></div>'+
      '<div class="grc-report-upload-field"><label>'+L('reportPages')+'</label><input name="pages" type="number" min="0" value="'+Number(existing&&existing.pages||0)+'"></div>'+
      '<div class="grc-report-upload-field full grc-report-filebox"><label>'+L('choosePdf')+'</label><input name="pdf" type="file" accept="application/pdf,.pdf" required><small>'+L('pdfOnly')+'</small></div></div>'+
      '<div class="grc-upload-progress" id="_grcUploadProgress"><span></span></div><div class="grc-upload-status" id="_grcUploadStatus"></div><div class="grc-modal-actions"><button type="button" class="grc-btn ghost" onclick="document.getElementById(\'_grcReportUploadModal\').remove()">'+L('cancel')+'</button><button type="submit" class="grc-upload-primary" id="_grcUploadBtn">'+L(existing?'replaceReport':'uploadReport')+'</button></div></form></div>';
    document.body.appendChild(ov);ov.addEventListener('click',function(e){if(e.target===ov)ov.remove();});
    var groupEl=document.getElementById('_grcUploadGroup'),quarterWrap=document.getElementById('_grcUploadQuarterWrap');function toggleQuarter(){quarterWrap.style.display=groupEl.value==='annual'?'none':'flex';}groupEl.addEventListener('change',toggleQuarter);toggleQuarter();
    document.getElementById('_grcReportUploadForm').addEventListener('submit',function(e){e.preventDefault();window._grcSubmitReportUpload(e.target,existing);});
  };
  window._grcSubmitReportUpload=async function(form,existing){
    if(!isGrcAdmin())return;
    var status=document.getElementById('_grcUploadStatus'),progress=document.getElementById('_grcUploadProgress'),bar=progress&&progress.querySelector('span'),btn=document.getElementById('_grcUploadBtn');
    try{
      var fd=new FormData(form),group=String(fd.get('group')||'quarterly'),kind=String(fd.get('kind')||'report'),year=Number(fd.get('year')),quarter=group==='quarterly'?Number(fd.get('quarter')):null,file=form.elements.pdf.files[0]||null;
      if(!file)throw new Error('invalid-pdf');
      if(!(file.type==='application/pdf'||/\.pdf$/i.test(file.name)))throw new Error('invalid-pdf');
      if(file.size>REPORT_MAX_BYTES)throw new Error('file-too-large');
      var type=reportTypeFromForm(group,kind),id=reportIdFor(type,year,quarter),titles=defaultReportTitles(group,kind,year,quarter),b=await ensureReportBackend();
      if(!b.auth.currentUser)throw new Error('not-authenticated');
      if(btn){btn.disabled=true;btn.textContent=L('uploading');}if(status)status.textContent=L('uploading');if(progress)progress.style.display='block';
      invalidateReportBlob(id);
      var oldChunkCount=Number(existing&&existing.chunkCount||0),oldChunkKey=String(existing&&existing.chunkKey||existing&&existing.id||''),version=Date.now(),chunkKey=id+'_'+version,chunkCount=await writePdfChunks(b,chunkKey,file,function(pct){if(bar)bar.style.width=pct+'%';if(status)status.textContent=L('uploading')+' '+pct+'%';});
      var defaultCode=group==='annual'?(kind==='executive'?'PRT-EAR-'+year:'PRT-AR-'+year):(kind==='executive'?'PRT-EQR-'+year+'-'+quarter:'RPT-QR-'+year+'-'+quarter);var record={id:id,group:group,type:type,year:year,quarter:quarter,titleEn:String(fd.get('titleEn')||titles.en).trim()||titles.en,titleAr:String(fd.get('titleAr')||titles.ar).trim()||titles.ar,code:String(fd.get('code')||defaultCode).trim()||defaultCode,language:String(fd.get('language')||'en'),versionLabel:String(fd.get('versionLabel')||'1.0').trim()||'1.0',issueDate:String(fd.get('issueDate')||''),owner:String(fd.get('owner')||'Governance & Performance').trim(),status:'active',pages:Number(fd.get('pages')||0),fileName:file.name,fileSize:file.size,contentType:'application/pdf',chunkCount:chunkCount,chunkKey:chunkKey,version:version,uploadedBy:window._fbUser||b.auth.currentUser.email||''};
      await updateReportIndex(b,record,null);
      if(oldChunkCount&&oldChunkKey)await deletePdfChunks(b,oldChunkKey,oldChunkCount);
      if(status)status.textContent=L('uploadComplete');try{if(typeof window.addAudit==='function')window.addAudit('REPORT_UPLOAD',(existing?'Replaced':'Uploaded')+' report: '+record.titleEn,null,record.fileName);}catch(_){}reportLibraryLoaded=false;await loadReportLibrary(true);reportNav={group:group,type:type,year:year,quarter:quarter};var modal=document.getElementById('_grcReportUploadModal');if(modal)modal.remove();render();
    }catch(err){console.error('[GRC Reports] upload failed',err);var msg=String(err&&err.code||err&&err.message||'');if(msg.indexOf('file-too-large')>=0)msg=L('fileTooLarge');else if(msg.indexOf('invalid-pdf')>=0)msg=L('invalidPdf');else msg=L('uploadFailed')+' '+msg;if(status)status.textContent=msg;if(btn){btn.disabled=false;btn.textContent=L(existing?'replaceReport':'uploadReport');}}
  };
  window._grcDeleteReport=async function(id){
    if(!isGrcAdmin()||!window.confirm(L('confirmDeleteReport')))return;
    var r=REPORT_LIBRARY.find(function(x){return String(x.id)===String(id);});if(!r)return;
    try{var b=await ensureReportBackend();await deletePdfChunks(b,r.chunkKey||r.id,r.chunkCount);await updateReportIndex(b,null,r.id);try{if(typeof window.addAudit==='function')window.addAudit('REPORT_DELETE','Deleted report: '+reportTitle(r),r.fileName,null);}catch(_){}invalidateReportBlob(r.id);reportNav={group:r.group,type:r.type,year:r.year,quarter:null};reportLibraryLoaded=false;await loadReportLibrary(true);render();}catch(err){console.error('[GRC Reports] delete failed',err);window.alert(L('uploadFailed')+' '+String(err&&err.code||err&&err.message||err));}
  };

