ch(err){console.error('[GRC Compliance] upload failed',err);var msg=String(err&&err.code||err&&err.message||'');if(msg.indexOf('file-too-large')>=0)msg=L('fileTooLarge');else if(msg.indexOf('invalid-pdf')>=0)msg=L('invalidPdf');else msg=L('uploadFailed')+' '+msg;if(status)status.textContent=msg;if(btn){btn.disabled=false;btn.textContent=existing?L('replaceReport'):(isAr()?'رفع PDF':'Upload PDF');}} 
