  window._grcDeleteOperationalPlan=async function(id){if(!isGrcAdmin()||!window.confirm(L('confirmDeleteReport')))return;var r=OP_PLAN_LIBRARY.find(function(x){return x.id===id;});if(!r)return;try{var b=await ensureReportBackend();await deletePdfChunks(b,r.chunkKey||r.id,r.chunkCount);await updateOpPlanIndex(b,null,r.id);try{if(typeof window.addAudit==='function')window.addAudit('OPERATIONAL_PLAN_DELETE','Deleted annual operational plan: '+(r.titleEn||r.id),r.fileName,null);}catch(_){}invalidateReportBlob(r.id);opPlanLibraryLoaded=false;await loadOpPlanLibrary(true);renderOperationalPlanModal();}catch(err){window.alert(L('uploadFailed'));}};
