  function pdfSearchBar(id,library){var key=esc(library)+'_'+esc(id);return'<div class="grc-pdf-search" data-pdf-search-key="'+key+'"><span class="grc-pdf-search-icon">⌕</span><input id="_grcPdfSearch_'+key+'" type="search" placeholder="'+(isAr()?'ابحث عن كلمة داخل الملف':'Search inside this PDF')+'" onkeydown="if(event.key===\'Enter\'){event.preventDefault();window._grcPdfSearch(\''+esc(id)+'\',\''+esc(library)+'\',this.value,1)}"><button type="button" onclick="var i=document.getElementById(\'_grcPdfSearch_'+key+'\');window._grcPdfSearch(\''+esc(id)+'\',\''+esc(library)+'\',i?i.value:\'\',1)">'+(isAr()?'بحث':'Search')+'</button><button class="grc-pdf-nav" type="button" title="Previous result" onclick="window._grcPdfSearchMove(\''+esc(id)+'\',\''+esc(library)+'\',-1)">‹</button><button class="grc-pdf-nav" type="button" title="Next result" onclick="window._grcPdfSearchMove(\''+esc(id)+'\',\''+esc(library)+'\',1)">›</button><strong id="_grcPdfCount_'+key+'">0 / 0</strong><span class="grc-pdf-zoom-sep"></span><button class="grc-pdf-nav" type="button" title="Zoom out" onclick="window._grcPdfZoom(\''+esc(id)+'\',\''+esc(library)+'\',-0.15)">−</button><strong id="_grcPdfZoom_'+key+'">100%</strong><button class="grc-pdf-nav" type="button" title="Zoom in" onclick="window._grcPdfZoom(\''+esc(id)+'\',\''+esc(library)+'\',0.15)">＋</button><button class="grc-pdf-nav" type="button" title="Fit width" onclick="window._grcPdfZoomFit(\''+esc(id)+'\',\''+esc(library)+'\')">↔</button></div>';}

  var _grcPdfViewerStates={};
  function _grcPdfKey(id,library){return String(library||'reports')+'::'+String(id);}
  function _grcPdfRecord(id,library){return library==='guides'?guideRecords().find(function(r){return String(r.id)===String(id);}):REPORT_LIBRARY.find(function(r){return String(r.id)===String(id);});}
  function _grcLoadPdfJs(){if(window.pdfjsLib)return Promise.resolve(window.pdfjsLib);if(window.__grcPdfJsPromise)return window.__grcPdfJsPromise;window.__grcPdfJsPromise=new Promise(function(resolve,reject){var sc=document.createElement('script');sc.src='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';sc.onload=function(){try{window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';resolve(window.pdfjsLib);}catch(e){reject(e);}};sc.onerror=reject;document.head.appendChild(sc);});return window.__grcPdfJsPromise;}
  function _grcNormalizeSearchText(v){return String(v||'').normalize('NFKC').replace(/[\u064B-\u065F\u0670\u06D6-\u06ED]/g,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').replace(/ؤ/g,'و').replace(/ئ/g,'ي').replace(/ة/g,'ه').replace(/[ـ\u200b-\u200f\u202a-\u202e\u2066-\u2069\ufeff]/g,'').replace(/\s+/g,' ').trim().toLowerCase();}
  function _grcCountOccurrences(text,query){var count=0,from=0;if(!query)return 0;while((from=text.indexOf(query,from))>=0){count++;from+=Math.max(1,query.length);}return count;}
  async function _grcMountPdfCanvas(el){var id=el.getAttribute('data-grc-report-id'),library=el.getAttribute('data-grc-library')||'reports',record=_grcPdfRecord(id,library);if(!record)return;var key=_grcPdfKey(id,library),state=_grcPdfViewerStates[key]||(_grcPdfViewerStates[key]={id:id,library:library,query:'',matches:[],matchIndex:-1,textCache:{},rendered:{},zoom:1});state.el=el;try{var pdfjs=await _grcLoadPdfJs(),url=await getReportBlobUrl(record);if(!state.pdf)state.pdf=await pdfjs.getDocument(url).promise;await _grcRenderAllPdfPages(state);}catch(err){console.error('[GRC PDF.js]',err);el.innerHTML='<iframe class="grc-report-frame" src="'+esc(await getReportBlobUrl(record))+'#toolbar=1&navpanes=0&view=FitH&page=1"></iframe>';}}
  async function _grcRenderAllPdfPages(state){if(!state.pdf||!state.el)return;state.el.innerHTML='<div class="grc-pdf-continuous-pages"></div>';var list=state.el.querySelector('.grc-pdf-continuous-pages');for(var p=1;p<=state.pdf.numPages;p++){var holder=document.createElement('section');holder.className='grc-pdf-page-holder';holder.setAttribute('data-page',String(p));holder.innerHTML='<div class="grc-pdf-page-number">'+p+' / '+state.pdf.numPages+'</div><div class="grc-pdf-page-placeholder">'+(isAr()?'جاري تحميل الصفحة':'Loading page')+' '+p+'…</div>';list.appendChild(holder);}var renderVisible=function(holder){var pageNo=Number(holder.getAttribute('data-page'));_grcRenderOnePdfPage(state,pageNo);};if('IntersectionObserver'in window){if(state.observer)state.observer.disconnect();state.observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting)renderVisible(entry.target);});},{root:state.el,rootMargin:'900px 0px'});list.querySelectorAll('.grc-pdf-page-holder').forEach(function(h){state.observer.observe(h);});}else{for(var i=1;i<=Math.min(5,state.pdf.numPages);i++)_grcRenderOnePdfPage(state,i);}await _grcRenderOnePdfPage(state,1);}
  async function _grcRenderOnePdfPage(state,pageNo){if(!state.pdf||!state.el||state.rendered[pageNo])return;var holder=state.el.querySelector('.grc-pdf-page-holder[data-page="'+pageNo+'"]');if(!holder)return;state.rendered[pageNo]='loading';try{var page=await state.pdf.getPage(pageNo),base=page.getViewport({scale:1}),maxWidth=Math.max(500,state.el.clientWidth-52),scale=Math.min(2.8,Math.max(.55,(maxWidth/base.width)*(Number(state.zoom)||1))),vp=page.getViewport({scale:scale});holder.innerHTML='<div class="grc-pdf-page-number">'+pageNo+' / '+state.pdf.numPages+'</div><div class="grc-pdf-page-stage"><canvas></canvas><div class="grc-pdf-text-layer"></div></div>';var canvas=holder.querySelector('canvas'),ctx=canvas.getContext('2d');canvas.width=Math.floor(vp.width);canvas.height=Math.floor(vp.height);canvas.style.width=vp.width+'px';canvas.style.height=vp.height+'px';await page.render({canvasContext:ctx,viewport:vp}).promise;var tc=await page.getTextContent(),layer=holder.querySelector('.grc-pdf-text-layer');layer.style.width=vp.width+'px';layer.style.height=vp.height+'px';layer.innerHTML='';tc.items.forEach(function(item){var tx=window.pdfjsLib.Util.transform(vp.transform,item.transform),fontHeight=Math.max(5,Math.hypot(tx[2],tx[3])),angle=Math.atan2(tx[1],tx[0]),sp=document.createElement('span');sp.textContent=String(item.str||'');sp.style.left=tx[4]+'px';sp.style.top=(tx[5]-fontHeight)+'px';sp.style.fontSize=fontHeight+'px';sp.style.fontFamily='sans-serif';sp.style.transform='rotate('+angle+'rad)';layer.appendChild(sp);});state.textCache[pageNo]=tc.items.map(function(x){return x.str;}).join(' ');state.rendered[pageNo]=true;_grcHighlightPdfPage(state,holder);}catch(err){state.rendered[pageNo]=false;holder.innerHTML='<div class="grc-pdf-page-number">'+pageNo+'</div><div class="grc-pdf-page-placeholder">'+(isAr()?'تعذر تحميل الصفحة':'Page could not be loaded')+'</div>';}}
  function _grcCompactPdfText(value){return _grcNormalizeSearchText(value).replace(/\s+/g,'');}
  function _grcPdfSearchVariants(items){
    var rows=(items||[]).map(function(x){return String(x||'');}),
      revRows=rows.slice().reverse(),
      reverseText=function(v){return Array.from(String(v||'')).reverse().join('');};
    return[
      rows,
      revRows,
      rows.map(reverseText),
      revRows.map(reverseText)
    ];
  }
  function _grcPdfVariantStream(spans,order,reverseChars){
    var text='',map=[];
    order.forEach(function(idx){
      var raw=String(spans[idx].textContent||''),
        part=_grcCompactPdfText(reverseChars?Array.from(raw).reverse().join(''):raw);
      for(var c=0;c<part.length;c++){text+=part[c];map.push(idx);}
    });
    return{text:text,map:map};
  }
  function _grcFindPdfOccurrences(hay,needle){
    var out=[],pos=0;
    while(needle&&(pos=hay.indexOf(needle,pos))>=0){
      out.push([pos,pos+needle.length]);
      pos+=Math.max(1,needle.length);
    }
    return out;
  }
  function _grcHighlightPdfPage(state,holder){
    if(!holder)return;
    var stage=holder.querySelector('.grc-pdf-page-stage'),
      qRaw=String(state.query||'').trim(),
      q=_grcCompactPdfText(qRaw),
      qReverse=Array.from(q).reverse().join(''),
      pageNo=Number(holder.getAttribute('data-page')),
      isCurrent=state.matchIndex>=0&&state.matches[state.matchIndex]&&state.matches[state.matchIndex].page===pageNo,
      spans=Array.prototype.slice.call(holder.querySelectorAll('.grc-pdf-text-layer span'));
    if(stage)stage.querySelectorAll('.grc-pdf-word-hit').forEach(function(x){x.remove();});
    if(!q||!stage||!spans.length)return;

    var stageRect=stage.getBoundingClientRect(),orders=[
      {order:spans.map(function(_,i){return i;}),reverseChars:false},
      {order:spans.map(function(_,i){return i;}).reverse(),reverseChars:false},
      {order:spans.map(function(_,i){return i;}),reverseChars:true},
      {order:spans.map(function(_,i){return i;}).reverse(),reverseChars:true}
    ],needles=[q];
    if(qReverse!==q)needles.push(qReverse);

    var selected=null;
    outer:for(var oi=0;oi<orders.length;oi++){
      var stream=_grcPdfVariantStream(spans,orders[oi].order,orders[oi].reverseChars);
      for(var ni=0;ni<needles.length;ni++){
        var found=_grcFindPdfOccurrences(stream.text,needles[ni]);
        if(found.length){selected={stream:stream,ranges:found,needle:needles[ni]};break outer;}
      }
    }

    var hitNo=0;
    if(selected){
      selected.ranges.forEach(function(range){
        var involved=[],seen={};
        for(var p=range[0];p<range[1];p++){
          var idx=selected.stream.map[p];
          if(idx!==undefined&&!seen[idx]){seen[idx]=1;involved.push(idx);}
        }
        involved.forEach(function(idx){
          var sp=spans[idx],rect=sp.getBoundingClientRect(),hit=document.createElement('div');
          hit.className='grc-pdf-word-hit'+(isCurrent&&hitNo===0?' current':'');
          hit.style.left=(rect.left-stageRect.left-1)+'px';
          hit.style.top=(rect.top-stageRect.top)+'px';
          hit.style.width=Math.max(3,rect.width+2)+'px';
          hit.style.height=Math.max(5,rect.height)+'px';
          stage.appendChild(hit);
        });
        hitNo++;
      });
    }
    holder.classList.toggle('grc-pdf-page-has-hit',hitNo>0);
    holder.classList.toggle('grc-pdf-page-current-hit',isCurrent&&hitNo>0);
  }
  function _grcHighlightPdf(state){if(!state.el)return;state.el.querySelectorAll('.grc-pdf-page-holder').forEach(function(holder){_grcHighlightPdfPage(state,holder);});}
  async function _grcBuildPdfMatches(state,query){
    state.matches=[];
    var q=_grcCompactPdfText(query),qReverse=Array.from(q).reverse().join('');
    if(!q)return;
    var needles=[q];
    if(qReverse!==q)needles.push(qReverse);
    for(var p=1;p<=state.pdf.numPages;p++){
      var pg=await state.pdf.getPage(p),tc=await pg.getTextContent(),
        items=tc.items.map(function(x){return String(x.str||'');}),
        variants=_grcPdfSearchVariants(items),bestCount=0;
      state.textCache[p]=items.join(' ');
      variants.forEach(function(rows){
        var hay=_grcCompactPdfText(rows.join(''));
        needles.forEach(function(needle){
          bestCount=Math.max(bestCount,_grcCountOccurrences(hay,needle));
        });
      });
      for(var i=0;i<bestCount;i++)state.matches.push({page:p,occurrence:i});
    }
  }
  function _grcUpdatePdfCount(state){var el=document.getElementById('_grcPdfCount_'+String(state.library)+'_'+String(state.id));if(el)el.textContent=state.matches.length?((state.matchIndex+1)+' / '+state.matches.length):'0 / 0';}
  async function _grcGoToPdfMatch(state){if(!state.matches.length||state.matchIndex<0)return;var match=state.matches[state.matchIndex],holder=state.el.querySelector('.grc-pdf-page-holder[data-page="'+match.page+'"]');await _grcRenderOnePdfPage(state,match.page);holder=state.el.querySelector('.grc-pdf-page-holder[data-page="'+match.page+'"]');_grcHighlightPdf(state);if(holder&&state.el){state.el.scrollTo({top:Math.max(0,holder.offsetTop-10),behavior:'smooth'});}}
