      '<div class="grc-org-viewer-head"><div><div class="grc-org-viewer-title">'+esc(dept?deptName(dept):L('orgChartTitle'))+'</div><div class="grc-org-viewer-sub">'+L('orgChartDesc')+'</div></div>'+
      '<div class="grc-org-toolbar"><button class="grc-org-tool" onclick="window._grcOrgZoom(-0.15)" aria-label="Zoom out">−</button><button class="grc-org-tool" onclick="window._grcOrgFit()">'+(isAr()?'ملاءمة':'Fit')+'</button><button class="grc-org-tool" onclick="window._grcOrgZoom(0.15)" aria-label="Zoom in">+</button><button class="grc-org-tool grc-org-close" onclick="document.getElementById(\'_grcOrgModal\').remove()" aria-label="Close">×</button></div></div>'+
      '<div class="grc-org-stage"><div class="grc-org-image-wrap" data-scale="1"><img class="grc-org-image" src="'+(dept&&DEPARTMENT_ORG_CHART_DATA_URIS[dept]?DEPARTMENT_ORG_CHART_DATA_URIS[dept]:ORG_CHART_DATA_URI)+'" onerror="if(!this.dataset.fallback){this.dataset.fallback=&quot;1&quot;;this.src=&quot;assets/fms-organizational-structure.png?v=20260729-v91&quot;;}" alt="'+esc(dept?deptName(dept):L('orgChartTitle'))+'"></div></div></div>';
    document.documentElement.appendChild(ov);
    var orgImg=ov.querySelector('.grc-org-image');if(orgImg)orgImg.addEventListener('load',function(){window._grcOrgFit();});
