  function _grcDataRows(block){
    var table=block&&block.querySelector('table');if(!table||!table.tBodies.length)return[];
    return Array.prototype.filter.call(table.tBodies[0].rows,function(row){
      return !row.classList.contains('grc-table-group')&&!row.classList.contains('grc-table-subgroup')&&!row.classList.contains('grc-table-group-empty')&&!row.querySelector('td[colspan]');
    });
  }
  function _grcRecordIdentity(r){return String(r&&r.id||r&&r.code||'').trim();}
  function _grcResolveRowRecord(block,map,row){
    var records=state[map.collection]||[],scope=map.scope||'',idCell=row.querySelector('.grc-id'),needle=String(idCell&&idCell.textContent||'').replace(/\s+/g,' ').trim();
    var foundIndex=-1;
    records.some(function(r,index){
      if(scope&&String(r.scope||r.formScope||'')!==scope)return false;
      var candidates=[r.id,r.code].filter(Boolean).map(function(v){return String(v).replace(/\s+/g,' ').trim();});
      var match=candidates.some(function(v){return v===needle||governanceCodeKey(v)===governanceCodeKey(needle);});
      if(match){foundIndex=index;return true;}return false;
    });
    if(foundIndex<0)return null;
    return{record:records[foundIndex],index:foundIndex};
  }
  function _grcNameField(record){
    var keys=['name','nameEn','title','titleEn','riskIdentified','description'];
    for(var i=0;i<keys.length;i++)if(Object.prototype.hasOwnProperty.call(record||{},keys[i]))return keys[i];
    return'name';
  }
  function _grcEditableField(header,record,map){
    var h=String(header||'').trim(),lower=h.toLowerCase().replace(/\s+/g,'');
    var aliases={
      name:'__name',manualName:'__name',title:'__name',riskId:'id',incidentId:'id',codeNumber:'id',manualId:'id',id:'id',
      code:'code',issueDate:'issueDate',effectiveDate:'effectiveDate',reviewDate:'reviewDate',status:'status',
      riskIdentified:'riskIdentified',riskCategory:'riskCategory',likelihood:'likelihood',impact:'impact',controlType:'controlType',actionStatus:'actionStatus',
      date:'date',category:'category',contributingFactors:'contributingFactors',investigationRequired:'investigationRequired',responsibleDept:'department',
      emergencyCodeType:'codeType',codeSubtype:'subtype',eventType:'type',location:'location',closeDateTime:'closeDateTime',department:'department',owner:'owner',
      source:'source',dueDate:'dueDate',progress:'progress'
    };
    if(aliases[h])h=aliases[h];
    else if(lower==='initiativecode'||lower==='كودالمبادرة')h='code';
    else if(lower==='arabicname'||lower==='اسمالمبادرةبالعربي')h='nameAr';
    else if(lower==='englishname'||lower==='اسمالمبادرةبالإنجليزي')h='nameEn';
    else if(lower==='executionstatus'||lower==='حالةالتنفيذ')h='executionStatus';
    else if(lower==='progress'||lower==='نسبةالإنجاز')h='progress';
    else if(lower==='team'||lower==='الفريق'||lower==='gender'||lower==='الجنس')return null;
    if(h==='__name')h=_grcNameField(record);
    if(h==='riskScore'||h==='riskLevel'||h==='score')return null;
    if(h==='effectiveDate'&&!Object.prototype.hasOwnProperty.call(record,'effectiveDate')&&Object.prototype.hasOwnProperty.call(record,'startDate'))h='startDate';
    if(h==='reviewDate'&&!Object.prototype.hasOwnProperty.call(record,'reviewDate')&&Object.prototype.hasOwnProperty.call(record,'expiryDate'))h='expiryDate';
    if(Object.prototype.hasOwnProperty.call(record,h)||['id','code','status','department','name','nameEn','nameAr','title','titleEn','executionStatus','progress'].indexOf(h)>=0)return h;
    return null;
  }
  function _grcInlineOptions(fieldName,map){
    if(fieldName==='department')return deptOptions();
    if(fieldName==='executionStatus')return[['planned',L('planned')],['in_progress',L('inProgress')],['completed',L('completed')]];
    if(fieldName==='status'||fieldName==='actionStatus')return statusOptions(map.type);
    if(fieldName==='investigationRequired')return[['yes',L('yes')],['no',L('no')]];
    if(fieldName==='type'&&map.type==='code')return[['real',L('real')],['drill',L('drill')]];
    return null;
  }
  function _grcInlineControl(record,fieldName,map){
    var value=record[fieldName]==null?'':record[fieldName],options=_grcInlineOptions(fieldName,map),html='';
    if(options){
      html='<select class="grc-inline-input" data-field="'+esc(fieldName)+'">'+options.map(function(o){return'<option value="'+esc(o[0])+'" '+(String(o[0])===String(value)?'selected':'')+'>'+esc(o[1])+'</option>';}).join('')+'</select>';
    }else{
      var type=/Date|date|At$/.test(fieldName)?'date':(['likelihood','impact','progress'].indexOf(fieldName)>=0?'number':'text');
      var extra=fieldName==='progress'?' min="0" max="100"':'';
      html='<input class="grc-inline-input" data-field="'+esc(fieldName)+'" type="'+type+'"'+extra+' value="'+esc(value)+'">';
    }
    return html;
  }
  function _grcSetInlineActions(block,map,mode){
    var actions=block.querySelector('.grc-inline-crud-actions');if(!actions)return;
    if(mode==='edit'){
      var sendMode=canSubmitRegisterRequest(map.type)&&!isGrcAdmin();
      actions.innerHTML='<button type="button" class="grc-btn primary" data-grc-inline-action="save">✓ '+(sendMode?(isAr()?'إرسال التعديلات للاعتماد':'Send Changes for Approval'):(isAr()?'حفظ التعديلات':'Save Changes'))+'</button><button type="button" class="grc-btn ghost" data-grc-inline-action="cancel">'+(isAr()?'إلغاء':'Cancel')+'</button>';
    }else if(mode==='delete'){
      actions.innerHTML='<span class="grc-inline-mode-note">'+(isAr()?'اضغط × بجانب السجل المطلوب حذفه':'Click × beside the record to delete it')+'</span><button type="button" class="grc-btn ghost" data-grc-inline-action="cancel">'+(isAr()?'إنهاء':'Done')+'</button>';
    }else actions.innerHTML=registerCrudButtons(map);
    _grcBindInlineActions(block,map);
  }
  function _grcBindInlineActions(block,map){
    var actions=block.querySelector('.grc-inline-crud-actions');if(!actions)return;
    Array.prototype.forEach.call(actions.querySelectorAll('[data-grc-inline-action]'),function(btn){
      btn.addEventListener('click',function(){
        var action=btn.getAttribute('data-grc-inline-action');
        if(action==='add'){var scopeArg=map.scope?map.scope:null;window._grcOpenForm(map.type,(canSubmitRegisterRequest(map.type)&&!isGrcAdmin())?(map.type==='risk'?currentRiskRecordDept():currentGrcDept()):null,scopeArg);}
        else if(action==='edit')_grcBeginInlineEdit(block,map);
        else if(action==='delete')_grcBeginInlineDelete(block,map);
        else if(action==='save')_grcSaveInlineEdit(block,map);
        else if(action==='cancel')renderAtSamePosition(grcViewportPosition());
      });
    });
  }
  function _grcBeginInlineEdit(block,map){
    var table=block.querySelector('table');if(!table)return;
    block.classList.add('grc-inline-edit-mode');
    var headerRow=table.tHead&&table.tHead.rows[0],headers=headerRow?Array.prototype.map.call(headerRow.cells,function(th){return th.getAttribute('data-field')||th.textContent.trim();}):[];
    _grcDataRows(block).forEach(function(row){
      var resolved=_grcResolveRowRecord(block,map,row);if(!resolved)return;
      if(canSubmitRegisterRequest(map.type)&&!isGrcAdmin()&&!registerRecordBelongsToUser(resolved.record,map.type))return;
      row.dataset.grcRecordIndex=resolved.index;
      Array.prototype.forEach.call(row.cells,function(cell,col){
        var fieldName=_grcEditableField(headers[col],resolved.record,map);
        if(!fieldName){cell.classList.add('grc-inline-locked');return;}
        cell.dataset.grcOriginalHtml=cell.innerHTML;
        cell.innerHTML=_grcInlineControl(resolved.record,fieldName,map);
        cell.classList.add('grc-inline-edit-cell');
      });
    });
    _grcSetInlineActions(block,map,'edit');
  }
  function _grcChangedRecordFields(before,after){
    before=before||{};after=after||{};var ignored={updatedAt:1,updatedBy:1,updatedByEmail:1,cloudUpdatedAt:1,_cloudLoadedAt:1};
    return Array.from(new Set(Object.keys(before).concat(Object.keys(after)))).filter(function(k){return !ignored[k]&&JSON.stringify(before[k]===undefined?'':before[k])!==JSON.stringify(after[k]===undefined?'':after[k]);});
  }
  function _grcCanDirectRiskStatusChange(original,updated,map){
    if(!map||map.type!=='risk'||['risk_owner','platform_owner'].indexOf(normalizedRole())<0)return false;
    var fields=_grcChangedRecordFields(original,updated),next=String(updated&&updated.actionStatus||'').toLowerCase();
    return fields.length===1&&fields[0]==='actionStatus'&&(next==='open'||next==='closed')&&registerRecordBelongsToUser(original,'risk');
  }
  async function _grcSaveInlineEdit(block,map){
    var records=state[map.collection]||[],changed=false,requests=[],directStatusUpdates=[];
    _grcDataRows(block).forEach(function(row){
      var index=Number(row.dataset.grcRecordIndex);if(!isFinite(index)||!records[index])return;
      var original=records[index],updated=Object.assign({},original);
      Array.prototype.forEach.call(row.querySelectorAll('.grc-inline-input'),function(input){
        var fieldName=input.getAttribute('data-field'),value=input.value;
        if(['likelihood','impact','progress'].indexOf(fieldName)>=0)value=Number(value||0);
        updated[fieldName]=value;
      });
      updated.updatedAt=new Date().toISOString();updated.updatedBy=currentName();updated=normalizeRecordBeforeSave(map.type,updated);
      var comparableOld=JSON.stringify(Object.assign({},original,{updatedAt:undefined,updatedBy:undefined})),comparableNew=JSON.stringify(Object.assign({},updated,{updatedAt:undefined,updatedBy:undefined}));
      if(comparableOld===comparableNew)return;
      if(canSubmitRegisterRequest(map.type)&&!isGrcAdmin()){
        if(_grcCanDirectRiskStatusChange(original,updated,map))directStatusUpdates.push({index:index,original:original,updated:updated});
        else requests.push({recordType:map.type,currentRecord:original,proposedRecord:updated,targetRiskId:original.id||original.code,targetRecordId:original.id||original.code,department:currentGrcDept()});
      }else{records[index]=updated;changed=true;}
    });
    try{
      if(directStatusUpdates.length){
        if(typeof window._grcRiskDirectStatusUpdate!=='function')throw new Error(isAr()?'خدمة تحديث حالة الخطر غير جاهزة.':'Direct risk status service is not ready.');
        for(var d=0;d<directStatusUpdates.length;d++){var item=directStatusUpdates[d];await window._grcRiskDirectStatusUpdate(item.original,item.updated.actionStatus);records[item.index]=item.updated;}
        state[map.collection]=records;
        window.toast&&window.toast(isAr()?'تم تحديث حالة الخطر مباشرة.':'Risk status updated directly.');
      }
      if(requests.length){
        if(typeof window._grcRiskRequestSubmit!=='function')throw new Error(isAr()?'خدمة طلبات السجلات غير جاهزة.':'Register approval service is not ready.');
        for(var i=0;i<requests.length;i++)await window._grcRiskRequestSubmit('update',requests[i]);
        window.toast&&window.toast((isAr()?'تم إرسال ':'Sent ')+requests.length+(isAr()?' طلب تعديل للاعتماد.':' update request(s) for approval.'));
      }
      if(changed){state[map.collection]=records;saveState();}
      else renderAtSamePosition(grcViewportPosition());
      if(window._grcRiskRefreshUi)window._grcRiskRefreshUi();
    }catch(err){window.alert(String(err&&err.message||err));}
  }
  function _grcBeginInlineDelete(block,map){
    var table=block.querySelector('table');if(!table)return;
    block.classList.add('grc-inline-delete-mode');
    var head=table.tHead&&table.tHead.rows[0];if(head){var th=document.createElement('th');th.className='grc-inline-delete-col';th.textContent='×';head.insertBefore(th,head.firstChild);}
    Array.prototype.forEach.call(table.tBodies[0].rows,function(row){
      if(row.querySelector('td[colspan]')){var span=row.querySelector('td[colspan]');span.colSpan=Number(span.colSpan||1)+1;return;}
      if(row.classList.contains('grc-table-group')||row.classList.contains('grc-table-subgroup')||row.classList.contains('grc-table-group-empty'))return;
      var resolved=_grcResolveRowRecord(block,map,row);if(!resolved)return;
      var td=document.createElement('td');td.className='grc-inline-delete-cell';
      var btn=document.createElement('button');btn.type='button';btn.className='grc-inline-delete-x';btn.textContent='×';btn.title=isAr()?'حذف السجل':'Delete record';
      btn.addEventListener('click',function(){
        var current=state[map.collection]&&state[map.collection][resolved.index];if(!current)return;
        var label=genericRecordLabel(current)||_grcRecordIdentity(current);
        var requestMode=canSubmitRegisterRequest(map.type)&&!isGrcAdmin();
        var message=(requestMode?(isAr()?'هل تريد إرسال طلب حذف هذا السجل؟\n':'Submit a request to delete this record?\n'):(isAr()?'هل تريد حذف هذا السجل نهائيًا؟\n':'Delete this record permanently?\n'))+label;
        if(!window.confirm(message))return;
        if(requestMode){var reason=window.prompt(isAr()?'سبب طلب الحذف:':'Reason for deletion request:','');if(reason===null)return;if(!String(reason).trim()){window.alert(isAr()?'سبب الحذف مطلوب.':'Deletion reason is required.');return;}if(typeof window._grcRiskRequestSubmit!=='function'){window.alert(isAr()?'خدمة طلبات السجلات غير جاهزة.':'Register approval service is not ready.');return;}window._grcRiskRequestSubmit('delete',{recordType:map.type,currentRecord:current,targetRiskId:current.id||current.code,targetRecordId:current.id||current.code,department:currentGrcDept(),deleteReason:reason}).then(function(){window.toast&&window.toast(isAr()?'تم إرسال طلب الحذف للاعتماد.':'Deletion request sent for approval.');renderAtSamePosition(grcViewportPosition());if(window._grcRiskRefreshUi)window._grcRiskRefreshUi();}).catch(function(err){window.alert(String(err&&err.message||err));});return;}
        state[map.collection].splice(resolved.index,1);saveState();
      });
      td.appendChild(btn);row.insertBefore(td,row.firstChild);
    });
    _grcSetInlineActions(block,map,'delete');
  }
  function enhanceAllRegisterCrud(){
    if(!app||(!isGrcAdmin()&&!canSubmitRiskRequest()&&!canSubmitIncidentRequest()))return;
    var candidates=app.querySelectorAll('.grc-register-block,.grc-section,.grc-card,.grc-table-card');
    Array.prototype.forEach.call(candidates,function(block){
      if(block.dataset.crudReady==='1'||!block.querySelector('table'))return;
      var titleEl=block.querySelector('.grc-register-name,.grc-register-title,.grc-section-title,.grc-card-title,h2,h3,h4,h5');
      if(!titleEl)return;
      var map=crudMapForTitle(titleEl.textContent);if(!map)return;
      if(!isGrcAdmin()&&!canSubmitRegisterRequest(map.type))return;
      if(canSubmitRegisterRequest(map.type)&&!isGrcAdmin()){
        var rows=_grcDataRows(block),matches=rows.some(function(row){var resolved=_grcResolveRowRecord(block,map,row);return resolved&&registerRecordBelongsToUser(resolved.record,map.type);});if(rows.length&&!matches)return;
      }
      var head=titleEl.closest('.grc-register-titlebar,.grc-register-head,.grc-section-head,.grc-card-head,header')||titleEl.parentElement;if(!head)return;
      var actions=head.querySelector('.grc-register-actions,.grc-section-actions,.grc-inline-crud-actions');
      if(!actions){actions=document.createElement('div');actions.className='grc-register-actions grc-inline-crud-actions';head.appendChild(actions);}else actions.classList.add('grc-inline-crud-actions');
      actions.innerHTML=registerCrudButtons(map);block.dataset.crudReady='1';_grcBindInlineActions(block,map);
    });
  }
